PathwayData.put("data/reading_writing/units/L03U4.json",{"strand":"reading_writing","level":3,"cefr":"A2a","unit":4,"theme":"Our Wonderful Body","essential_question":"How does our body work, and how can we look after it?","schema_version":"1.0","core_words":["heart","lungs","bones","muscles","brain","stomach","skin","teeth","exercise","breathe","blood","strong","rest","sleep"],"recycled_words":["healthy","water","fruit","sleep","because","so","first","also","in addition","fact","opinion","energy","strong"],"rubrics":[{"id":"RW-RUBRIC-5T","title":"Analytic writing rubric","traits":[{"name":"Ideas","name_ar":"الأفكار","bands":[{"score":4,"descriptor":"My ideas are clear, interesting and fully developed with strong details.","descriptor_ar":"أفكاري واضحة وممتعة ومدعومة بتفاصيل قوية."},{"score":3,"descriptor":"My ideas are clear and have enough details.","descriptor_ar":"أفكاري واضحة ومعها تفاصيل كافية."},{"score":2,"descriptor":"My main idea is there but needs more details.","descriptor_ar":"فكرتي الرئيسية موجودة لكنها تحتاج إلى تفاصيل أكثر."},{"score":1,"descriptor":"My ideas are unclear or very few.","descriptor_ar":"أفكاري غير واضحة أو قليلة جدًا."}]},{"name":"Organization","name_ar":"التنظيم","bands":[{"score":4,"descriptor":"Clear beginning, middle and end; ideas flow with linking words.","descriptor_ar":"بداية ووسط ونهاية واضحة، والأفكار مترابطة بكلمات الربط."},{"score":3,"descriptor":"Clear order with some linking words.","descriptor_ar":"ترتيب واضح مع بعض كلمات الربط."},{"score":2,"descriptor":"Some order, but parts are mixed up.","descriptor_ar":"يوجد بعض الترتيب لكن بعض الأجزاء غير مرتبة."},{"score":1,"descriptor":"Ideas are not in order.","descriptor_ar":"الأفكار غير مرتبة."}]},{"name":"Vocabulary","name_ar":"المفردات","bands":[{"score":4,"descriptor":"I use exact, varied words, including new unit words, correctly.","descriptor_ar":"أستخدم كلمات دقيقة ومتنوعة، منها كلمات الوحدة الجديدة، بشكل صحيح."},{"score":3,"descriptor":"I use some new words correctly.","descriptor_ar":"أستخدم بعض الكلمات الجديدة بشكل صحيح."},{"score":2,"descriptor":"I use simple words; some are repeated or wrong.","descriptor_ar":"أستخدم كلمات بسيطة، وبعضها مكرر أو غير صحيح."},{"score":1,"descriptor":"I use very few words; the meaning is hard to understand.","descriptor_ar":"أستخدم كلمات قليلة جدًا ويصعب فهم المعنى."}]},{"name":"Sentence fluency","name_ar":"سلاسة الجمل","bands":[{"score":4,"descriptor":"My sentences are complete, varied in length and easy to read aloud.","descriptor_ar":"جملي كاملة ومتنوعة الطول وسهلة القراءة بصوت عالٍ."},{"score":3,"descriptor":"Most sentences are complete, with some variety.","descriptor_ar":"معظم جملي كاملة مع بعض التنويع."},{"score":2,"descriptor":"Many sentences are short or start the same way.","descriptor_ar":"كثير من جملي قصيرة أو تبدأ بالطريقة نفسها."},{"score":1,"descriptor":"Sentences are incomplete or run together.","descriptor_ar":"جملي ناقصة أو متداخلة."}]},{"name":"Conventions","name_ar":"قواعد الكتابة","bands":[{"score":4,"descriptor":"Capitals, punctuation, spelling and grammar are almost always correct.","descriptor_ar":"الحروف الكبيرة وعلامات الترقيم والإملاء والقواعد صحيحة دائمًا تقريبًا."},{"score":3,"descriptor":"A few mistakes that do not affect meaning.","descriptor_ar":"أخطاء قليلة لا تؤثر في المعنى."},{"score":2,"descriptor":"Several mistakes; the meaning is sometimes unclear.","descriptor_ar":"عدة أخطاء، والمعنى أحيانًا غير واضح."},{"score":1,"descriptor":"Many mistakes make it hard to read.","descriptor_ar":"أخطاء كثيرة تجعل القراءة صعبة."}]}]}],"lessons":[{"id":"RW-L03-U4-LS1","title":"Word Power: Our Wonderful Body","lesson_type":"vocabulary","objectives":["read, say and use 14 words about the human body and health and 3 Tier 2 words (function, inform, persuade)","use the prefixes un- (not) and re- (again) to build and understand new words","name body parts and say what each one does"],"objectives_ar":["قراءة ونطق واستخدام 14 كلمة عن جسم الإنسان والصحة و3 كلمات أكاديمية (function, inform, persuade).","استخدام البادئتين un- (ليس/غير) وre- (مرة أخرى) لبناء كلمات جديدة وفهمها.","تسمية أجزاء الجسم وذكر وظيفة كل منها."],"success_criteria":["I can read and use the body words in sentences.","I can explain a word with un- or re- (unhealthy = not healthy).","I can say the function of three body parts."],"success_criteria_ar":["أستطيع قراءة كلمات الجسم واستخدامها في جمل.","أستطيع شرح كلمة فيها un- أو re-.","أستطيع ذكر وظيفة ثلاثة أجزاء من الجسم."],"map_area":"Vocabulary: Acquisition and Use","vocabulary":[{"word":"heart","pos":"noun","ipa":"/hɑrt/","definition":"the organ in your chest that pumps blood around your body","arabic":"القلب","example":"Your heart beats all day and all night.","image_id":"IMG-RW-L03-U4-LS1-V01","audio_id":"AUD-RW-L03-U4-LS1-V01","tier":"core"},{"word":"lungs","pos":"noun","ipa":"/lʌŋz/","definition":"the two organs in your chest that take in air","arabic":"الرئتان","example":"Your lungs fill with air when you breathe in.","image_id":"IMG-RW-L03-U4-LS1-V02","audio_id":"AUD-RW-L03-U4-LS1-V02","tier":"core"},{"word":"bones","pos":"noun","ipa":"/boʊnz/","definition":"the hard white parts inside your body","arabic":"العظام","example":"Milk helps your bones grow strong.","image_id":"IMG-RW-L03-U4-LS1-V03","audio_id":"AUD-RW-L03-U4-LS1-V03","tier":"core"},{"word":"muscles","pos":"noun","ipa":"/ˈmʌsəlz/","definition":"the parts of your body that help you move","arabic":"العضلات","example":"Exercise makes your muscles strong.","image_id":"IMG-RW-L03-U4-LS1-V04","audio_id":"AUD-RW-L03-U4-LS1-V04","tier":"core"},{"word":"brain","pos":"noun","ipa":"/breɪn/","definition":"the organ in your head that you think with","arabic":"الدماغ","example":"Your brain helps you learn and remember.","image_id":"IMG-RW-L03-U4-LS1-V05","audio_id":"AUD-RW-L03-U4-LS1-V05","tier":"core"},{"word":"stomach","pos":"noun","ipa":"/ˈstʌmək/","definition":"the organ where food goes after you eat","arabic":"المعدة","example":"My stomach is full after lunch.","image_id":"IMG-RW-L03-U4-LS1-V06","audio_id":"AUD-RW-L03-U4-LS1-V06","tier":"core"},{"word":"skin","pos":"noun","ipa":"/skɪn/","definition":"the outside cover of your body","arabic":"الجلد","example":"Sunscreen protects your skin.","image_id":"IMG-RW-L03-U4-LS1-V07","audio_id":"AUD-RW-L03-U4-LS1-V07","tier":"core"},{"word":"teeth","pos":"noun","ipa":"/tiθ/","definition":"the hard white things in your mouth for biting and chewing (one tooth)","arabic":"الأسنان","example":"Brush your teeth twice a day.","image_id":"IMG-RW-L03-U4-LS1-V08","audio_id":"AUD-RW-L03-U4-LS1-V08","tier":"core"},{"word":"exercise","pos":"noun / verb","ipa":"/ˈɛksərsaɪz/","definition":"moving your body to stay healthy; to do this","arabic":"تمرين / يمارس الرياضة","example":"Exercise is good for your heart.","image_id":"IMG-RW-L03-U4-LS1-V09","audio_id":"AUD-RW-L03-U4-LS1-V09","tier":"core"},{"word":"breathe","pos":"verb","ipa":"/brið/","definition":"to take air into your body and let it out","arabic":"يتنفس","example":"Breathe in slowly through your nose.","image_id":"IMG-RW-L03-U4-LS1-V10","audio_id":"AUD-RW-L03-U4-LS1-V10","tier":"core"},{"word":"blood","pos":"noun","ipa":"/blʌd/","definition":"the red liquid that moves around your body","arabic":"الدم","example":"Your heart pumps blood.","image_id":"IMG-RW-L03-U4-LS1-V11","audio_id":"AUD-RW-L03-U4-LS1-V11","tier":"core"},{"word":"strong","pos":"adjective","ipa":"/strɔŋ/","definition":"having a lot of power; not weak","arabic":"قوي","example":"Strong bones help you stand and run.","image_id":"IMG-RW-L03-U4-LS1-V12","audio_id":"AUD-RW-L03-U4-LS1-V12","tier":"core"},{"word":"rest","pos":"verb / noun","ipa":"/rɛst/","definition":"to stop and relax; a time of relaxing","arabic":"يرتاح / راحة","example":"Rest after you play football.","image_id":"IMG-RW-L03-U4-LS1-V13","audio_id":"AUD-RW-L03-U4-LS1-V13","tier":"core"},{"word":"sleep","pos":"verb / noun","ipa":"/slip/","definition":"to close your eyes and rest your body and brain at night","arabic":"ينام / نوم","example":"Children need about ten hours of sleep.","image_id":"IMG-RW-L03-U4-LS1-V14","audio_id":"AUD-RW-L03-U4-LS1-V14","tier":"core"},{"word":"function","pos":"noun","ipa":"/ˈfʌŋkʃən/","definition":"the job that something does","arabic":"وظيفة","example":"The function of the lungs is to take in air.","image_id":"IMG-RW-L03-U4-LS1-V15","audio_id":"AUD-RW-L03-U4-LS1-V15","tier":"tier2"},{"word":"inform","pos":"verb","ipa":"/ɪnˈfɔrm/","definition":"to give facts and information","arabic":"يُخبر / يُعلِم","example":"This article informs us about the heart.","image_id":"IMG-RW-L03-U4-LS1-V16","audio_id":"AUD-RW-L03-U4-LS1-V16","tier":"tier2"},{"word":"persuade","pos":"verb","ipa":"/pərˈsweɪd/","definition":"to try to make someone agree or do something","arabic":"يُقنع","example":"The poster persuades us to eat fruit.","image_id":"IMG-RW-L03-U4-LS1-V17","audio_id":"AUD-RW-L03-U4-LS1-V17","tier":"tier2"}],"explanation":{"text":"A **prefix** is a small word part added to the **beginning** of a word. It changes the meaning.\n\n**un-** means **not** (or the opposite): *un + healthy = **unhealthy** (not healthy)*; *un + lock = **unlock** (the opposite of lock)*.\n\n**re-** means **again**: *re + fill = **refill** (fill again)*; *re + read = **reread** (read again)*. To find the meaning: cover the prefix, read the **base word**, then add *not* or *again*.","examples":["**un + healthy = unhealthy** – not healthy: *Too much candy is unhealthy.*","**un + safe = unsafe** – not safe: *Running near the pool is unsafe.*","**un + happy = unhappy** – not happy.","**un + tie = untie** – the opposite of tie: *Untie your shoes before you take them off.*","**re + fill = refill** – fill again: *Refill your water bottle after exercise.*","**re + build = rebuild** – build again: *Your body can rebuild muscles while you sleep.*","**re + read = reread** – read again: *Reread the text to find the answer.*","**re + start = restart** – start again.","Careful: some words only LOOK like they have a prefix: *uncle, under, red, ready* – no prefix!"],"common_errors":["✗ unhealthy means healthy again. → ✓ unhealthy means not healthy. (**un-** = not; **re-** = again.)","✗ rehappy → ✓ happy again (rehappy is not a word) (Not every base word takes every prefix – check it is a real word.)","✗ Breath deeply. → ✓ Breathe deeply. (**breathe** (verb, with e) / **breath** (noun).)","✗ My tooths are clean. → ✓ My teeth are clean. (One **tooth**, two **teeth**.)","✗ Exercise make the heart strong. → ✓ Exercise makes the heart strong. (Exercise (one thing) → **makes**.)","✗ I sleep 10 hours in night. → ✓ I sleep ten hours at night. (Say **at night**.)","✗ The brain function is to think. → ✓ The function of the brain is to think. (Say **the function of** + part.)"],"arabic":"البادئة (prefix) جزء صغير يُضاف إلى أول الكلمة فيغيّر معناها.\n\nun- تعني «غير/ليس» أو العكس: unhealthy = غير صحي، unlock = يفتح القفل.\n\nre- تعني «مرة أخرى»: refill = يعيد الملء، reread = يعيد القراءة.\n\nانتبه: بعض الكلمات تبدو كأن لها بادئة وليست كذلك: uncle, under, ready. وانتبه أيضًا: breathe فعل، وbreath اسم."},"video":{"script":[{"time":"00:00–00:20","narration":"Your body is an amazing machine! Let's take a tour inside with Adam.","on_screen":"Our Wonderful Body","visual":"Adam shrinks and rides a tiny car into a friendly cartoon body."},{"time":"00:20–01:05","narration":"The heart pumps blood. The lungs breathe air. The brain thinks. The stomach holds food.","on_screen":"heart · lungs · blood · breathe · brain · stomach","visual":"Each organ lights up with its job."},{"time":"01:05–01:35","narration":"Bones and muscles help you move. Skin covers you. Teeth bite and chew!","on_screen":"bones · muscles · skin · teeth","visual":"A skeleton dances; a muscle flexes; teeth chew an apple."},{"time":"01:35–02:00","narration":"Stay strong: exercise, rest and sleep!","on_screen":"exercise · rest · sleep · strong","visual":"Children skip rope, sit in the shade, then sleep under the stars."},{"time":"02:00–02:45","narration":"Prefixes! un- means not: unhealthy. re- means again: refill!","on_screen":"un- = not · re- = again","visual":"Prefix blocks snap onto base words; meanings pop up."},{"time":"02:45–03:00","narration":"Every part has a function. Some texts inform, some persuade!","on_screen":"function · inform · persuade","visual":"A heart with a job label; a poster saying 'Move more!'"}],"captions_ar":["جسمك آلة مدهشة! لنقم بجولة في داخله مع آدم.","القلب يضخ الدم، والرئتان تتنفسان الهواء، والدماغ يفكر، والمعدة تحفظ الطعام.","العظام والعضلات تساعدك على الحركة، والجلد يغطيك، والأسنان تقطع وتمضغ!","ابقَ قويًا: مارس الرياضة واسترح ونم!","البادئات! un- تعني «غير»: unhealthy، وre- تعني «مرة أخرى»: refill!","لكل جزء وظيفة. وبعض النصوص تُعلِم وبعضها يُقنع!"],"voice":"Narrator: American English, cheerful female teacher, speed 0.90. Adam (the Researcher): curious and clear."},"texts":[],"activities":[{"id":"RW-L03-U4-LS1-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Choose the correct word.","instructions_ar":"اختر الكلمة الصحيحة.","items":[{"q":"The organ that pumps blood around your body is the ___.","answer":"heart","explanation":"Heart = pumps blood.","explanation_ar":"القلب.","options":["brain","stomach","heart","skin"],"dok":1,"skill":"body parts","stage":"controlled"},{"q":"You use your ___ to think and remember.","answer":"brain","explanation":"Brain = think.","explanation_ar":"الدماغ.","options":["lungs","teeth","brain","bones"],"dok":1,"skill":"body parts","stage":"controlled"},{"q":"Air goes into your ___ when you breathe in.","answer":"lungs","explanation":"Lungs take in air.","explanation_ar":"الرئتين.","options":["lungs","stomach","bones","heart"],"dok":1,"skill":"body parts","stage":"controlled"},{"q":"Food goes to your ___ after you eat.","answer":"stomach","explanation":"Stomach = food.","explanation_ar":"المعدة.","options":["brain","stomach","lungs","skin"],"dok":1,"skill":"body parts","stage":"controlled"},{"q":"Brush your ___ twice a day.","answer":"teeth","explanation":"Teeth = brush.","explanation_ar":"أسنانك.","options":["lungs","bones","muscles","teeth"],"dok":1,"skill":"body parts","stage":"controlled"},{"q":"The ___ help you move your arms and legs.","answer":"muscles","explanation":"Muscles = move.","explanation_ar":"العضلات.","options":["muscles","teeth","lungs","skin"],"dok":1,"skill":"body parts","stage":"controlled"}]},{"id":"RW-L03-U4-LS1-A2","type":"mcq","stage":"guided","instructions":"Guided practice: Prefixes un- and re-. Choose.","instructions_ar":"البادئتان un- وre-: اختر.","items":[{"q":"*Unhealthy* means ___.","answer":"not healthy","explanation":"un- = not.","explanation_ar":"غير صحي.","options":["healthy again","very healthy","not healthy","a healthy heart"],"dok":1,"skill":"prefixes","stage":"guided"},{"q":"*Refill* means ___.","answer":"fill again","explanation":"re- = again.","explanation_ar":"يعيد الملء.","options":["not fill","fill a little","never fill","fill again"],"dok":1,"skill":"prefixes","stage":"guided"},{"q":"Which word means *not safe*?","answer":"unsafe","explanation":"un + safe.","explanation_ar":"unsafe.","options":["resafe","unsafe","safely","safer"],"dok":1,"skill":"prefixes","stage":"guided"},{"q":"Which word means *read again*?","answer":"reread","explanation":"re + read.","explanation_ar":"reread.","options":["unread","reread","reader","reading"],"dok":1,"skill":"prefixes","stage":"guided"},{"q":"Which word does NOT have a prefix?","answer":"uncle","explanation":"'uncle' is one word, not un + cle.","explanation_ar":"uncle.","options":["unhappy","rebuild","untie","uncle"],"dok":2,"skill":"prefixes","stage":"guided"},{"q":"*Your body can rebuild muscles while you sleep.* *Rebuild* means ___.","answer":"build again","explanation":"re + build.","explanation_ar":"يعيد البناء.","options":["build again","break","not build","build for the first time"],"dok":2,"skill":"prefixes in context","stage":"guided"}]},{"id":"RW-L03-U4-LS1-A3","type":"gap_fill","stage":"freer","instructions":"Freer practice: Use the word bank.","instructions_ar":"استخدم بنك الكلمات.","items":[{"q":"The ________ of the stomach is to break down food.","answer":"function","explanation":"The job that something does.","explanation_ar":"وظيفة.","stage":"freer"},{"q":"This poster wants to ________ us to drink more water.","answer":"persuade","explanation":"Try to make us do something.","explanation_ar":"يقنعنا.","stage":"freer"},{"q":"The article will ________ you about how bones grow.","answer":"inform","explanation":"Give facts.","explanation_ar":"يُعلِمك.","stage":"freer"},{"q":"Your heart pumps ________ to every part of your body.","answer":"blood","explanation":"Red liquid.","explanation_ar":"الدم.","stage":"freer"},{"q":"Children need about ten hours of ________ every night.","answer":"sleep","explanation":"Rest at night.","explanation_ar":"نوم.","stage":"freer"},{"q":"Climbing stairs makes your leg muscles ________.","answer":"strong","explanation":"Not weak.","explanation_ar":"قوية.","stage":"freer"}]},{"id":"RW-L03-U4-LS1-A4","type":"open","stage":"production","instructions":"Writing: Write with the new words.","instructions_ar":"اكتب باستخدام الكلمات الجديدة.","items":[{"q":"Write the function of two body parts.","answer":"The function of the heart is to pump blood. The function of the lungs is to take in air.","explanation":"Two functions.","explanation_ar":"وظيفتان.","dok":2,"skill":"functions","stage":"production"},{"q":"Write a sentence with *unhealthy* and one with *refill*.","answer":"Eating too much candy is unhealthy. I refill my water bottle at school.","explanation":"Two prefixed words.","explanation_ar":"كلمتان ببادئة.","dok":2,"skill":"prefixes","stage":"production"},{"q":"What do you do to keep your body strong?","answer":"I exercise every day, and I sleep early.","explanation":"Healthy habits.","explanation_ar":"عادات صحية.","dok":2,"skill":"connect","stage":"production"},{"q":"Which body part do you think is the most important? Why?","answer":"The brain, because it controls all the other parts.","explanation":"Opinion + because.","explanation_ar":"رأي + because.","dok":3,"skill":"opinion","stage":"production"}]}],"game":{"name":"Body Builder","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Body builder: an empty body outline appears; the child drags each organ to its place and chooses its function. Bonus round: add un- or re- to words to power up the body's energy bar.","Teams get a body outline and body-part cards.","Teams place each part in the right place.","For each part, they match a function card (pumps blood, takes in air…).","Bonus: build three real un-/re- words and use one in a health sentence.","Correct part + function = 2 points; bonus words = 1 point each."],"data":[]},"exit_quiz":[{"q":"Which word means *the job that something does*?","answer":"function","explanation":"Function = job.","explanation_ar":"وظيفة.","options":["muscle","persuade","function","rest"],"dok":1,"skill":"vocabulary"},{"q":"The prefix *re-* means ___.","answer":"again","explanation":"re- = again.","explanation_ar":"مرة أخرى.","options":["not","full of","without","again"],"dok":1,"skill":"prefixes"},{"q":"The prefix *un-* means ___.","answer":"not","explanation":"un- = not.","explanation_ar":"غير.","options":["again","before","after","not"],"dok":1,"skill":"prefixes"},{"q":"What is the function of the lungs?","answer":"to take in air","explanation":"Lungs → air.","explanation_ar":"إدخال الهواء.","options":["to take in air","to pump blood","to break down food","to think"],"dok":1,"skill":"functions"},{"q":"Which sentence about teeth is correct?","answer":"My teeth are white and strong.","explanation":"teeth (plural) + are.","explanation_ar":"صحيحة.","options":["My teeth are white and strong.","My tooths are white.","My teeth is white.","My tooth are strong."],"dok":2,"skill":"grammar"},{"q":"Which sentence about breathing uses the verb correctly?","answer":"Breathe in slowly through your nose.","explanation":"breathe = verb.","explanation_ar":"breathe فعل.","options":["Breath in slowly through your nose.","Breathe in slowly through your nose.","Breathes in slowly.","Breathing in slowly through."],"dok":2,"skill":"spelling"},{"q":"*Wearing a seatbelt is a must. Driving without it is unsafe.* *Unsafe* means ___.","answer":"not safe","explanation":"un + safe.","explanation_ar":"غير آمن.","options":["safe again","not safe","very safe","a little safe"],"dok":1,"skill":"prefixes in context"},{"q":"A poster says *Move more, sit less!* What does it want to do?","answer":"persuade you to exercise","explanation":"It tries to make you act.","explanation_ar":"إقناعك بالحركة.","options":["inform you about the brain","entertain you with a story","persuade you to exercise","teach you to read"],"dok":2,"skill":"author's purpose"},{"q":"Why is it useful to know *un-* and *re-*?","answer":"You can work out the meaning of many new words.","explanation":"Prefixes unlock meanings.","explanation_ar":"لفهم كلمات كثيرة.","options":["They make words shorter.","They only work with body words.","You can work out the meaning of many new words.","They tell you the time."],"dok":3,"skill":"strategy"},{"q":"Which pair of habits helps your muscles AND your bones?","answer":"exercise and drinking milk","explanation":"Exercise and calcium help both.","explanation_ar":"الرياضة وشرب الحليب.","options":["exercise and drinking milk","sitting all day and eating candy","sleeping late and skipping breakfast","watching TV and drinking soda"],"dok":3,"skill":"apply"}],"images":[{"id":"IMG-RW-L03-U4-LS1-V01","prompt":"Picture for the word 'heart': a simple diagram of a heart in a chest"},{"id":"IMG-RW-L03-U4-LS1-V02","prompt":"Picture for the word 'lungs': a diagram of two lungs"},{"id":"IMG-RW-L03-U4-LS1-V03","prompt":"Picture for the word 'bones': a friendly skeleton waving"},{"id":"IMG-RW-L03-U4-LS1-V04","prompt":"Picture for the word 'muscles': an arm flexing a muscle"},{"id":"IMG-RW-L03-U4-LS1-V05","prompt":"Picture for the word 'brain': a cartoon brain with a light bulb"},{"id":"IMG-RW-L03-U4-LS1-V06","prompt":"Picture for the word 'stomach': a diagram of the stomach"},{"id":"IMG-RW-L03-U4-LS1-V07","prompt":"Picture for the word 'skin': a hand with a sunscreen drop"},{"id":"IMG-RW-L03-U4-LS1-V08","prompt":"Picture for the word 'teeth': a smile with clean teeth and a toothbrush"},{"id":"IMG-RW-L03-U4-LS1-V09","prompt":"Picture for the word 'exercise': children skipping rope"},{"id":"IMG-RW-L03-U4-LS1-V10","prompt":"Picture for the word 'breathe': a child breathing in with arrows"},{"id":"IMG-RW-L03-U4-LS1-V11","prompt":"Picture for the word 'blood': a drop of blood and tiny red cells"},{"id":"IMG-RW-L03-U4-LS1-V12","prompt":"Picture for the word 'strong': a child lifting a small weight easily"},{"id":"IMG-RW-L03-U4-LS1-V13","prompt":"Picture for the word 'rest': a child sitting in the shade with water"},{"id":"IMG-RW-L03-U4-LS1-V14","prompt":"Picture for the word 'sleep': a child sleeping with a moon outside"},{"id":"IMG-RW-L03-U4-LS1-V15","prompt":"Picture for the word 'function': gears turning with a label 'job'"},{"id":"IMG-RW-L03-U4-LS1-V16","prompt":"Picture for the word 'inform': a book with an 'i' (information) icon"},{"id":"IMG-RW-L03-U4-LS1-V17","prompt":"Picture for the word 'persuade': a poster with 'Eat more fruit!' and a thumbs-up"},{"id":"IMG-RW-L03-U4-LS1-01","prompt":"A body diagram surrounded by children doing healthy activities."},{"id":"IMG-RW-L03-U4-LS1-02","prompt":"Prefix blocks joining base words."},{"id":"IMG-RW-L03-U4-LS1-03","prompt":"A child counting heartbeats before and after jumping."}],"audio":[{"id":"AUD-RW-L03-U4-LS1-V01","script":"heart. Your heart beats all day and all night."},{"id":"AUD-RW-L03-U4-LS1-V02","script":"lungs. Your lungs fill with air when you breathe in."},{"id":"AUD-RW-L03-U4-LS1-V03","script":"bones. Milk helps your bones grow strong."},{"id":"AUD-RW-L03-U4-LS1-V04","script":"muscles. Exercise makes your muscles strong."},{"id":"AUD-RW-L03-U4-LS1-V05","script":"brain. Your brain helps you learn and remember."},{"id":"AUD-RW-L03-U4-LS1-V06","script":"stomach. My stomach is full after lunch."},{"id":"AUD-RW-L03-U4-LS1-V07","script":"skin. Sunscreen protects your skin."},{"id":"AUD-RW-L03-U4-LS1-V08","script":"teeth. Brush your teeth twice a day."},{"id":"AUD-RW-L03-U4-LS1-V09","script":"exercise. Exercise is good for your heart."},{"id":"AUD-RW-L03-U4-LS1-V10","script":"breathe. Breathe in slowly through your nose."},{"id":"AUD-RW-L03-U4-LS1-V11","script":"blood. Your heart pumps blood."},{"id":"AUD-RW-L03-U4-LS1-V12","script":"strong. Strong bones help you stand and run."},{"id":"AUD-RW-L03-U4-LS1-V13","script":"rest. Rest after you play football."},{"id":"AUD-RW-L03-U4-LS1-V14","script":"sleep. Children need about ten hours of sleep."},{"id":"AUD-RW-L03-U4-LS1-V15","script":"function. The function of the lungs is to take in air."},{"id":"AUD-RW-L03-U4-LS1-V16","script":"inform. This article informs us about the heart."},{"id":"AUD-RW-L03-U4-LS1-V17","script":"persuade. The poster persuades us to eat fruit."},{"id":"AUD-RW-L03-U4-LS1-VID","script":"Your body is an amazing machine! Let's take a tour inside with Adam. The heart pumps blood. The lungs breathe air. The brain thinks. The stomach holds food. Bones and muscles help you move. Skin covers you. Teeth bite and chew! Stay strong: exercise, rest and sleep! Prefixes! un- means not: unhealthy. re- means again: refill! Every part has a function. Some texts inform, some persuade!"}]},{"id":"RW-L03-U4-LS2","title":"Your Busy Heart","lesson_type":"close_reading","objectives":["read a science article of about 200 words and explain how the heart works as a process","connect causes and effects in the process (when you run → your heart beats faster)","answer literal, inferential and evaluative questions with evidence and numbers"],"objectives_ar":["قراءة مقال علمي من نحو 200 كلمة وشرح عمل القلب كعملية متسلسلة.","ربط الأسباب بالنتائج في العملية.","الإجابة عن أسئلة حرفية واستنتاجية وتقييمية بالدليل والأرقام."],"success_criteria":["I can explain the steps of how blood moves around the body.","I can explain why the heart beats faster when I exercise.","I can use definition clues and facts from the text in my answers."],"success_criteria_ar":["أستطيع شرح خطوات حركة الدم في الجسم.","أستطيع شرح لماذا يخفق القلب أسرع عند ممارسة الرياضة.","أستطيع استخدام أدلة التعريف والحقائق من النص في إجاباتي."],"map_area":"Informational Text: Key Ideas and Details","vocabulary":[{"word":"chest","pos":"noun","ipa":"/tʃɛst/","definition":"the front part of your body between your neck and stomach","arabic":"الصدر","example":"Your heart is inside your chest.","image_id":"IMG-RW-L03-U4-LS2-V01","audio_id":"AUD-RW-L03-U4-LS2-V01","tier":"core"},{"word":"beat","pos":"noun / verb","ipa":"/bit/","definition":"one push of the heart; to make this movement","arabic":"نبضة / ينبض","example":"Can you feel a beat?","image_id":"IMG-RW-L03-U4-LS2-V02","audio_id":"AUD-RW-L03-U4-LS2-V02","tier":"core"},{"word":"fist","pos":"noun","ipa":"/fɪst/","definition":"a hand with the fingers closed tightly","arabic":"قبضة اليد","example":"Your heart is about the size of your fist.","image_id":"IMG-RW-L03-U4-LS2-V03","audio_id":"AUD-RW-L03-U4-LS2-V03","tier":"core"},{"word":"pump","pos":"noun / verb","ipa":"/pʌmp/","definition":"a machine that pushes liquid or air; to push it","arabic":"مضخة / يضخ","example":"The heart works like a pump.","image_id":"IMG-RW-L03-U4-LS2-V04","audio_id":"AUD-RW-L03-U4-LS2-V04","tier":"core"},{"word":"blood vessels","pos":"noun","ipa":"/blʌd ˈvɛsəlz/","definition":"tubes that carry blood around the body","arabic":"الأوعية الدموية","example":"Blood moves through blood vessels.","image_id":"IMG-RW-L03-U4-LS2-V05","audio_id":"AUD-RW-L03-U4-LS2-V05","tier":"core"},{"word":"oxygen","pos":"noun","ipa":"/ˈɑksɪdʒən/","definition":"a gas in the air that our bodies need","arabic":"الأكسجين","example":"Your lungs take in oxygen.","image_id":"IMG-RW-L03-U4-LS2-V06","audio_id":"AUD-RW-L03-U4-LS2-V06","tier":"core"},{"word":"process","pos":"noun","ipa":"/ˈprɑsɛs/","definition":"a set of steps that happen in order","arabic":"عملية (خطوات متتابعة)","example":"Moving blood is a process.","image_id":"IMG-RW-L03-U4-LS2-V07","audio_id":"AUD-RW-L03-U4-LS2-V07","tier":"core"}],"explanation":{"text":"Science texts often explain **how something works**. They describe a **process** – steps that happen in order, again and again.\n\nLook for **order words** (every time, then, again) and **cause → effect words** (when, so, because). Draw the process as a **cycle** of arrows.\n\nTo explain a process, say each step in order and tell **why** it happens: *When you run, your muscles need more oxygen, **so** your heart beats faster.*","examples":["Step 1: **The heart beats and pushes blood.**","Step 2: **Blood travels through blood vessels to every part of the body.**","Step 3: **Blood carries oxygen and food to the body.**","Step 4: **The body uses oxygen and food to make energy.**","Step 5: **The blood comes back to the heart, and the trip starts again.**","Cause → effect: **When you run, your muscles need more oxygen, so your heart beats faster.**","Cause → effect: **When you rest, your heart beats slowly.**","Definition clue: **oxygen, a gas from the air** – the comma gives the meaning.","Number fact: **about 100,000 beats every day**."],"common_errors":["✗ The heart is in the stomach. → ✓ The heart is in the chest. (Check the facts in the text.)","✗ When I run, my heart beats slowly. → ✓ When I run, my heart beats faster. (Exercise → **faster**.)","✗ Blood carry oxygen. → ✓ Blood carries oxygen. (Blood (one thing) → **carries**.)","✗ The heart beat 100,000 times. → ✓ The heart beats about 100,000 times every day. (One heart → **beats**; keep **about** – it is not exact.)","✗ Explaining only one step. → ✓ Explain **all** the steps in order. (A process has many steps.)","✗ The heart is a bone. → ✓ The heart is a muscle. (The text says it is a **muscle**.)"],"arabic":"كثيرًا ما تشرح النصوص العلمية كيف يعمل شيء ما، فتصف عملية: خطوات تحدث بالترتيب مرة بعد مرة.\n\nابحث عن كلمات الترتيب (every time, then, again) وكلمات السبب والنتيجة (when, so, because)، وارسم العملية دائرة من الأسهم.\n\nلشرح العملية اذكر كل خطوة بالترتيب وقل لماذا تحدث: When you run, your muscles need more oxygen, so your heart beats faster.\n\nالقلب عضلة بحجم قبضة اليد تقريبًا، ويعمل مثل المضخة."},"video":{"script":[{"time":"00:00–00:20","narration":"Put your hand on your chest. Thump-thump! Let's ride with the blood!","on_screen":"Your Busy Heart ❤️","visual":"Adam's tiny car enters a big friendly heart."},{"time":"00:20–01:35","narration":"Your heart is a muscle about the size of your fist. It works like a pump…","on_screen":"(article, section by section)","visual":"The heart pumps; blood cells carry little oxygen bubbles and food packets through vessels to the brain and toes, then return."},{"time":"01:35–02:10","narration":"It's a process: beat → push → travel → deliver → come back → again!","on_screen":"Process cycle 🔄","visual":"A circle of arrows with five step icons."},{"time":"02:10–02:40","narration":"When you run, your muscles need more oxygen, SO your heart beats faster!","on_screen":"Cause → effect","visual":"A child runs; a heart icon speeds up; muscles glow."},{"time":"02:40–03:00","narration":"Look after your heart: move, eat well, drink water and sleep!","on_screen":"Healthy heart tips","visual":"Four quick icons: football, apple, water bottle, moon."}],"captions_ar":["ضع يدك على صدرك… دق دق! لنركب مع الدم!","قلبك عضلة بحجم قبضة يدك تقريبًا، ويعمل مثل المضخة…","إنها عملية: نبض ← دفع ← انتقال ← توصيل ← عودة ← من جديد!","عندما تجري تحتاج عضلاتك إلى أكسجين أكثر، لذلك يخفق قلبك أسرع!","اعتنِ بقلبك: تحرّك، وكُل جيدًا، واشرب الماء، ونم!"],"voice":"Narrator: American English, warm female teacher, speed 0.90. Adam rides with the blood like a tour guide."},"texts":[{"type":"reading","title":"Your Busy Heart","body":"Put your hand on the left side of your chest. Can you feel a beat? That is your heart, and it never stops working!\n\n**A Strong Pump**\n\nYour heart is a muscle about the size of your fist. It works like a pump. Every time it beats, it pushes blood through long tubes called blood vessels. The blood travels to every part of your body, from your brain to your toes.\n\n**What Does Blood Carry?**\n\nBlood carries oxygen, a gas from the air, and food from your stomach. Your body needs oxygen and food to make energy. Then the blood comes back to your heart, and the trip starts again.\n\n**Fast and Slow**\n\nYour heart beats about 100,000 times every day! When you rest, it beats slowly. When you run or play football, your muscles need more oxygen, so your heart beats faster.\n\n**Look After Your Heart**\n\nYou can keep your heart healthy. Move and play for one hour every day. Eat fruit and vegetables. Drink water instead of soda. Sleep well at night. A healthy heart will work hard for you your whole life!","word_count":186,"audio_id":"AUD-RW-L03-U4-LS2-T1","id":"TXT-RW-L03-U4-LS2-1","genre":"informational","role":"main","difficulty":"350L–500L","glossary":[{"word":"pump","definition":"a machine that pushes liquid or air","arabic":"مضخة"},{"word":"blood vessels","definition":"tubes that carry blood around the body","arabic":"الأوعية الدموية"},{"word":"oxygen","definition":"a gas in the air that our body needs","arabic":"الأكسجين"}]}],"activities":[{"id":"RW-L03-U4-LS2-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Read the article. Choose the answer.","instructions_ar":"اقرأ المقال واختر الإجابة.","items":[{"q":"Where is your heart?","answer":"on the left side of your chest","explanation":"Paragraph 1.","explanation_ar":"الجهة اليسرى من الصدر.","options":["in your head","in your stomach","in your right foot","on the left side of your chest"],"dok":1,"skill":"key details: where","stage":"controlled"},{"q":"How big is your heart?","answer":"about the size of your fist","explanation":"A Strong Pump.","explanation_ar":"بحجم القبضة.","options":["as big as a football","about the size of your fist","as small as a seed","as big as your head"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"What does the heart push through blood vessels?","answer":"blood","explanation":"A Strong Pump.","explanation_ar":"الدم.","options":["air","blood","food only","water"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"What two things does blood carry?","answer":"oxygen and food","explanation":"What Does Blood Carry?","explanation_ar":"الأكسجين والغذاء.","options":["bones and skin","water and soda","air and teeth","oxygen and food"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"About how many times does your heart beat every day?","answer":"about 100,000 times","explanation":"Fast and Slow.","explanation_ar":"نحو 100,000 مرة.","options":["about 100,000 times","about 100 times","about 1,000 times","about 10 times"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"How long should you move and play every day, says the article?","answer":"one hour","explanation":"Look After Your Heart.","explanation_ar":"ساعة واحدة.","options":["five minutes","five hours","one hour","all night"],"dok":1,"skill":"key details","stage":"controlled"}]},{"id":"RW-L03-U4-LS2-A2","type":"mcq","stage":"guided","instructions":"Guided practice: The process and cause and effect. Choose.","instructions_ar":"العملية والسبب والنتيجة: اختر.","items":[{"q":"What happens right AFTER the heart beats?","answer":"It pushes blood through blood vessels.","explanation":"Every time it beats, it pushes blood.","explanation_ar":"يدفع الدم.","options":["It pushes blood through blood vessels.","The blood stops.","You fall asleep.","Food goes to the stomach."],"dok":1,"skill":"process","stage":"guided"},{"q":"What happens after the blood delivers oxygen and food?","answer":"It comes back to the heart, and the trip starts again.","explanation":"Paragraph: What Does Blood Carry?","explanation_ar":"يعود إلى القلب.","options":["It leaves the body.","It comes back to the heart, and the trip starts again.","It turns into water.","It goes to sleep."],"dok":2,"skill":"process","stage":"guided"},{"q":"Why does your heart beat faster when you run?","answer":"Your muscles need more oxygen.","explanation":"Cause: muscles need more oxygen.","explanation_ar":"العضلات تحتاج إلى أكسجين أكثر.","options":["You are sleeping.","You drink soda.","Your bones get bigger.","Your muscles need more oxygen."],"dok":2,"skill":"cause and effect","stage":"guided"},{"q":"Why does the body need oxygen and food?","answer":"to make energy","explanation":"Text: to make energy.","explanation_ar":"لإنتاج الطاقة.","options":["to make energy","to grow hair","to make soda","to stop the heart"],"dok":2,"skill":"cause and effect","stage":"guided"},{"q":"Which words in the text tell you what *oxygen* means?","answer":"a gas from the air","explanation":"Definition clue after the comma.","explanation_ar":"a gas from the air.","options":["from your stomach","every part of your body","a gas from the air","about the size of your fist"],"dok":1,"skill":"definition clues","stage":"guided"},{"q":"What does the writer compare the heart to?","answer":"a pump","explanation":"It works like a pump.","explanation_ar":"مضخة.","options":["a computer","a camel","a bicycle","a pump"],"dok":1,"skill":"comparison","stage":"guided"}]},{"id":"RW-L03-U4-LS2-A3","type":"highlight","stage":"freer","instructions":"Find the evidence: Find the evidence.","instructions_ar":"ابحث عن الدليل.","items":[{"q":"Underline the sentence that explains why the heart beats faster during exercise.","answer":"When you run or play football, your muscles need more oxygen, so your heart beats faster.","explanation":"when… so…","explanation_ar":"عندما… لذلك…","evidence":"When you run or play football, your muscles need more oxygen, so your heart beats faster.","text_id":"TXT-RW-L03-U4-LS2-1","dok":2,"skill":"evidence","stage":"freer","sentences":["Put your hand on the left side of your chest.","Can you feel a beat?","That is your heart, and it never stops working!","**A Strong Pump**","Your heart is a muscle about the size of your fist.","It works like a pump.","Every time it beats, it pushes blood through long tubes called blood vessels.","The blood travels to every part of your body, from your brain to your toes.","**What Does Blood Carry?**","Blood carries oxygen, a gas from the air, and food from your stomach.","Your body needs oxygen and food to make energy.","Then the blood comes back to your heart, and the trip starts again.","**Fast and Slow**","Your heart beats about 100,000 times every day!","When you rest, it beats slowly.","When you run or play football, your muscles need more oxygen, so your heart beats faster.","**Look After Your Heart**","You can keep your heart healthy.","Move and play for one hour every day.","Eat fruit and vegetables.","Drink water instead of soda.","Sleep well at night.","A healthy heart will work hard for you your whole life!"]},{"q":"Underline the sentence that shows the process is a cycle.","answer":"Then the blood comes back to your heart, and the trip starts again.","explanation":"starts again = cycle.","explanation_ar":"يبدأ من جديد = دورة.","evidence":"Then the blood comes back to your heart, and the trip starts again.","text_id":"TXT-RW-L03-U4-LS2-1","dok":2,"skill":"evidence","stage":"freer","sentences":["Put your hand on the left side of your chest.","Can you feel a beat?","That is your heart, and it never stops working!","**A Strong Pump**","Your heart is a muscle about the size of your fist.","It works like a pump.","Every time it beats, it pushes blood through long tubes called blood vessels.","The blood travels to every part of your body, from your brain to your toes.","**What Does Blood Carry?**","Blood carries oxygen, a gas from the air, and food from your stomach.","Your body needs oxygen and food to make energy.","Then the blood comes back to your heart, and the trip starts again.","**Fast and Slow**","Your heart beats about 100,000 times every day!","When you rest, it beats slowly.","When you run or play football, your muscles need more oxygen, so your heart beats faster.","**Look After Your Heart**","You can keep your heart healthy.","Move and play for one hour every day.","Eat fruit and vegetables.","Drink water instead of soda.","Sleep well at night.","A healthy heart will work hard for you your whole life!"]},{"q":"The last section gives tips. What is its purpose?","answer":"to persuade readers to look after their hearts","explanation":"Tips try to make you act.","explanation_ar":"إقناع القارئ بالعناية بقلبه.","options":["to tell a funny story","to describe the size of the heart","to persuade readers to look after their hearts","to list the parts of the brain"],"dok":3,"skill":"author's purpose","stage":"freer"},{"q":"What is the main idea of *Your Busy Heart*?","answer":"The heart is a strong pump that moves blood around the body all the time, and we can keep it healthy.","explanation":"It covers all sections.","explanation_ar":"القلب مضخة قوية تعمل دائمًا ويمكن الحفاظ عليها.","options":["Blood is red.","The heart is a strong pump that moves blood around the body all the time, and we can keep it healthy.","Football is fun.","Soda is sweet."],"dok":3,"skill":"main idea","stage":"freer"}]},{"id":"RW-L03-U4-LS2-A4","type":"open","stage":"production","instructions":"Writing: Explain and evaluate.","instructions_ar":"اشرح وقيّم.","items":[{"q":"Explain the heart's process in three steps.","answer":"The heart beats and pushes blood. The blood carries oxygen and food to the body. Then it comes back to the heart.","explanation":"Three steps in order.","explanation_ar":"ثلاث خطوات مرتبة.","dok":2,"skill":"process","stage":"production"},{"q":"Write a cause → effect sentence about resting.","answer":"When you rest, your heart beats slowly.","explanation":"When… , …","explanation_ar":"When… , …","dok":2,"skill":"cause and effect","stage":"production"},{"q":"Why does the writer say *Drink water instead of soda*?","answer":"Because water is healthier for the heart than sugary soda.","explanation":"Inference.","explanation_ar":"استنتاج.","dok":3,"skill":"inference","stage":"production"},{"q":"Which heart tip will you follow this week? How?","answer":"I will play football for one hour after school instead of watching TV.","explanation":"Plan + how.","explanation_ar":"خطة + كيف.","dok":2,"skill":"connect","stage":"production"}]},{"id":"RW-L03-U4-LS2-TR-1","type":"timed_reading","instructions":"Timed reading: Read \"Your Busy Heart\" aloud or silently. Try to finish in the time.","instructions_ar":"اقرأ النص وحاول أن تنهيه في الوقت المحدد.","items":[{"q":"Read “Your Busy Heart”.","answer":"186 words","title":"Your Busy Heart","body":"Put your hand on the left side of your chest. Can you feel a beat? That is your heart, and it never stops working!\n\n**A Strong Pump**\n\nYour heart is a muscle about the size of your fist. It works like a pump. Every time it beats, it pushes blood through long tubes called blood vessels. The blood travels to every part of your body, from your brain to your toes.\n\n**What Does Blood Carry?**\n\nBlood carries oxygen, a gas from the air, and food from your stomach. Your body needs oxygen and food to make energy. Then the blood comes back to your heart, and the trip starts again.\n\n**Fast and Slow**\n\nYour heart beats about 100,000 times every day! When you rest, it beats slowly. When you run or play football, your muscles need more oxygen, so your heart beats faster.\n\n**Look After Your Heart**\n\nYou can keep your heart healthy. Move and play for one hour every day. Eat fruit and vegetables. Drink water instead of soda. Sleep well at night. A healthy heart will work hard for you your whole life!","words":186,"limit":174}],"time_limit_sec":174}],"game":{"name":"Blood Cell Relay","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Blood cell run: the child guides a blood cell along a path; at each station they tap the right action (pick up oxygen at the lungs, drop it at the muscles…). Correct steps make the heart beat louder.","Teams line up at the 'heart' station.","Player 1 carries a bean bag to the lungs and picks up an oxygen card.","Player 2 takes it to the muscles or brain and says what happens there.","The team returns to the heart and says 'The trip starts again!'","Correct steps and explanations = points; fastest correct team wins."],"data":[]},"exit_quiz":[{"q":"What is *Your Busy Heart* mostly about?","answer":"how the heart works and how to keep it healthy","explanation":"All sections are about the heart.","explanation_ar":"عمل القلب والعناية به.","options":["how to play football","the bones in your hand","how the heart works and how to keep it healthy","a trip to the hospital"],"dok":1,"skill":"main topic"},{"q":"The heart is a ___.","answer":"muscle","explanation":"Text: Your heart is a muscle.","explanation_ar":"عضلة.","options":["bone","tooth","muscle","lung"],"dok":1,"skill":"key details"},{"q":"*Blood vessels* are ___.","answer":"tubes that carry blood","explanation":"Text: long tubes called blood vessels.","explanation_ar":"أنابيب تحمل الدم.","options":["kinds of bones","tubes that carry blood","parts of the stomach","very small hearts"],"dok":1,"skill":"vocabulary"},{"q":"A set of steps that happen in order is a ___.","answer":"process","explanation":"Process = steps in order.","explanation_ar":"عملية.","options":["process","fist","chest","pump"],"dok":1,"skill":"vocabulary"},{"q":"When does your heart beat slowly?","answer":"when you rest","explanation":"Fast and Slow section.","explanation_ar":"عند الراحة.","options":["when you run","when you rest","when you play football","when you climb stairs"],"dok":1,"skill":"cause and effect"},{"q":"Which sentence about blood is correct?","answer":"Blood carries oxygen to the body.","explanation":"Blood → carries.","explanation_ar":"صحيحة.","options":["Blood carries oxygen to the body.","Blood carry oxygen to the body.","Blood carrying oxygen to the body.","Bloods carries oxygen."],"dok":2,"skill":"grammar"},{"q":"Which heading would you read to find heart-health tips?","answer":"Look After Your Heart","explanation":"Tips section.","explanation_ar":"Look After Your Heart.","options":["A Strong Pump","What Does Blood Carry?","Fast and Slow","Look After Your Heart"],"dok":1,"skill":"text features"},{"q":"Why does the writer start with *Put your hand on the left side of your chest*?","answer":"to get the reader interested by feeling their own heart","explanation":"A hook for the reader.","explanation_ar":"لجذب اهتمام القارئ.","options":["to tell a story about a doctor","to give a rule for football","to show a map","to get the reader interested by feeling their own heart"],"dok":2,"skill":"author's craft"},{"q":"Sami's heart is beating very fast. What was he MOST likely doing?","answer":"running in a race","explanation":"Exercise → faster.","explanation_ar":"يجري في سباق.","options":["sleeping","running in a race","reading quietly","sitting in class"],"dok":3,"skill":"inference"},{"q":"Which habit would be BAD for your heart, based on the article?","answer":"drinking lots of soda and never moving","explanation":"Opposite of the tips.","explanation_ar":"شرب المشروبات الغازية وعدم الحركة.","options":["drinking lots of soda and never moving","playing for one hour a day","eating fruit","sleeping well"],"dok":3,"skill":"apply"}],"images":[{"id":"IMG-RW-L03-U4-LS2-V01","prompt":"Picture for the word 'chest': a child pointing to his chest"},{"id":"IMG-RW-L03-U4-LS2-V02","prompt":"Picture for the word 'beat': a heart with a beat line"},{"id":"IMG-RW-L03-U4-LS2-V03","prompt":"Picture for the word 'fist': a closed fist next to a heart"},{"id":"IMG-RW-L03-U4-LS2-V04","prompt":"Picture for the word 'pump': a water pump pushing water through a pipe"},{"id":"IMG-RW-L03-U4-LS2-V05","prompt":"Picture for the word 'blood vessels': red and blue tubes in an arm"},{"id":"IMG-RW-L03-U4-LS2-V06","prompt":"Picture for the word 'oxygen': an O2 bubble going into lungs"},{"id":"IMG-RW-L03-U4-LS2-V07","prompt":"Picture for the word 'process': a circle of arrows"},{"id":"IMG-RW-L03-U4-LS2-01","prompt":"A heart diagram with blood vessels and a fist for size."},{"id":"IMG-RW-L03-U4-LS2-02","prompt":"A child resting with a slow heartbeat and playing football with a fast heartbeat."},{"id":"IMG-RW-L03-U4-LS2-03","prompt":"A cycle showing how blood moves."}],"audio":[{"id":"AUD-RW-L03-U4-LS2-V01","script":"chest. Your heart is inside your chest."},{"id":"AUD-RW-L03-U4-LS2-V02","script":"beat. Can you feel a beat?"},{"id":"AUD-RW-L03-U4-LS2-V03","script":"fist. Your heart is about the size of your fist."},{"id":"AUD-RW-L03-U4-LS2-V04","script":"pump. The heart works like a pump."},{"id":"AUD-RW-L03-U4-LS2-V05","script":"blood vessels. Blood moves through blood vessels."},{"id":"AUD-RW-L03-U4-LS2-V06","script":"oxygen. Your lungs take in oxygen."},{"id":"AUD-RW-L03-U4-LS2-V07","script":"process. Moving blood is a process."},{"id":"AUD-RW-L03-U4-LS2-T1","script":"Put your hand on the left side of your chest. Can you feel a beat? That is your heart, and it never stops working! **A Strong Pump** Your heart is a muscle about the size of your fist. It works like a pump. Every time it beats, it pushes blood through long tubes called blood vessels. The blood travels to every part of your body, from your brain to your toes. **What Does Blood Carry?** Blood carries oxygen, a gas from the air, and food from your stomach. Your body needs oxygen and food to make energy. Then the blood comes back to your heart, and the trip starts again. **Fast and Slow** Your heart beats about 100,000 times every day! When you rest, it beats slowly. When you run or play football, your muscles need more oxygen, so your heart beats faster. **Look After Your Heart** You can keep your heart healthy. Move and play for one hour every day. Eat fruit and vegetables. Drink water instead of soda. Sleep well at night. A healthy heart will work hard for you your whole life!"},{"id":"AUD-RW-L03-U4-LS2-VID","script":"Put your hand on your chest. Thump-thump! Let's ride with the blood! Your heart is a muscle about the size of your fist. It works like a pump… It's a process: beat → push → travel → deliver → come back → again! When you run, your muscles need more oxygen, SO your heart beats faster! Look after your heart: move, eat well, drink water and sleep!"}]},{"id":"RW-L03-U4-LS3","title":"Author's purpose: inform, entertain, persuade: \"Ibn Sina: The Young Doctor\"","lesson_type":"strategy_paired_text","objectives":["identify the author's purpose: to persuade, to inform or to entertain (PIE)","find clues in a text that show the author's purpose","compare the purposes of a science article, a biography and a story"],"objectives_ar":["تحديد غرض الكاتب: الإقناع أو الإعلام أو الإمتاع.","إيجاد الأدلة في النص التي تُظهر غرض الكاتب.","مقارنة أغراض مقال علمي وسيرة شخصية وقصة."],"success_criteria":["I can say the three main purposes for writing.","I can give a clue from the text that shows the purpose.","I can explain why a text can have more than one purpose."],"success_criteria_ar":["أستطيع ذكر الأغراض الثلاثة الرئيسية للكتابة.","أستطيع ذكر دليل من النص يُظهر الغرض.","أستطيع شرح لماذا قد يكون للنص أكثر من غرض."],"map_area":"Informational Text: Language, Craft, and Structure","vocabulary":[{"word":"biography","pos":"noun","ipa":"/baɪˈɑɡrəfi/","definition":"a true story of a real person's life, written by someone else","arabic":"سيرة شخصية","example":"We read a biography of Ibn Sina.","image_id":"IMG-RW-L03-U4-LS3-V01","audio_id":"AUD-RW-L03-U4-LS3-V01","tier":"core"},{"word":"medicine","pos":"noun","ipa":"/ˈmɛdɪsɪn/","definition":"the study of health and illness; something you take to get better","arabic":"الطب / الدواء","example":"Ibn Sina studied medicine.","image_id":"IMG-RW-L03-U4-LS3-V02","audio_id":"AUD-RW-L03-U4-LS3-V02","tier":"core"},{"word":"ruler","pos":"noun","ipa":"/ˈrulər/","definition":"a person who leads a country or city, like a king","arabic":"حاكم","example":"The ruler of Bukhara was ill.","image_id":"IMG-RW-L03-U4-LS3-V03","audio_id":"AUD-RW-L03-U4-LS3-V03","tier":"core"},{"word":"ill","pos":"adjective","ipa":"/ɪl/","definition":"sick","arabic":"مريض","example":"The ruler became very ill.","image_id":"IMG-RW-L03-U4-LS3-V04","audio_id":"AUD-RW-L03-U4-LS3-V04","tier":"core"},{"word":"memorize","pos":"verb","ipa":"/ˈmɛməraɪz/","definition":"to learn something by heart","arabic":"يحفظ","example":"He memorized the whole Quran.","image_id":"IMG-RW-L03-U4-LS3-V05","audio_id":"AUD-RW-L03-U4-LS3-V05","tier":"core"},{"word":"curiosity","pos":"noun","ipa":"/ˌkjʊriˈɑsəti/","definition":"wanting to know and learn about things","arabic":"حب الاستطلاع / الفضول","example":"Curiosity helped Ibn Sina learn.","image_id":"IMG-RW-L03-U4-LS3-V06","audio_id":"AUD-RW-L03-U4-LS3-V06","tier":"core"},{"word":"entertain","pos":"verb","ipa":"/ˌɛntərˈteɪn/","definition":"to make someone enjoy something","arabic":"يُمتع / يُسلّي","example":"Funny stories entertain us.","image_id":"IMG-RW-L03-U4-LS3-V07","audio_id":"AUD-RW-L03-U4-LS3-V07","tier":"core"}],"explanation":{"text":"Every author writes for a **reason**. This is the **author's purpose**. Remember **PIE**: **P**ersuade, **I**nform, **E**ntertain.\n\n**Persuade** – the author wants you to **think or do** something (*Drink water instead of soda!*). **Inform** – the author gives **facts** and teaches you (*Your heart beats about 100,000 times a day.*). **Entertain** – the author wants you to **enjoy** a story or poem (characters, a problem, funny parts).\n\nLook for **clues**: facts and numbers → inform; *you should, must, best* and tips → persuade; characters, feelings and a problem → entertain. A text can have **more than one** purpose, but one is usually the **main** purpose.","examples":["Inform: *Your heart is a muscle about the size of your fist.* (fact)","Persuade: *Move and play for one hour every day. Drink water instead of soda.* (tips telling you what to do)","Entertain: *The Saturday Clean-Up* – characters, a problem and a happy ending.","Biography → mostly **inform**: *Ibn Sina wrote a huge book about medicine.* (facts about a real person)","Biography clue: dates and numbers – *more than 1,000 years ago, at sixteen, hundreds of years*.","A biography can also **inspire**: *curiosity and hard work can help the whole world*.","Poem *The Desert Fox at Night* → **entertain** (rhyme and rhythm) **and** inform (facts about the fox).","Poster *Brush Your Teeth Twice a Day!* → **persuade**.","Ask: **Why did the author write this? What do they want me to know, do or enjoy?**"],"common_errors":["✗ Every text with facts is a story. → ✓ A text with facts is usually written to **inform**. (Facts → inform.)","✗ A biography is made up. → ✓ A biography tells the **true** story of a real person. (Biography = true.)","✗ Giving the purpose with no clue. → ✓ The purpose is to inform because the text gives dates and facts. (Always give a **clue**.)","✗ Ibn Sina memorize the Quran. → ✓ Ibn Sina memorized the Quran. (Biographies use the **past tense**.)","✗ The ruler was ill so Ibn Sina was a ruler. → ✓ The ruler was ill, so Ibn Sina helped him. (Check that the cause leads to the effect.)","✗ A text can only have one purpose. → ✓ A text can have more than one purpose, but one is the main one. (Look for the **main** purpose.)"],"arabic":"كل كاتب يكتب لسبب، وهذا هو غرض الكاتب. تذكّر PIE: الإقناع (Persuade)، والإعلام (Inform)، والإمتاع (Entertain).\n\nالإقناع: يريد الكاتب أن تفكر أو تفعل شيئًا. الإعلام: يقدّم حقائق ويعلّمك. الإمتاع: يريدك أن تستمتع بقصة أو قصيدة.\n\nابحث عن الأدلة: الحقائق والأرقام للإعلام، وكلمات مثل you should وthe best والنصائح للإقناع، والشخصيات والمشاعر والمشكلة للإمتاع.\n\nقد يكون للنص أكثر من غرض، لكن يكون أحدها هو الغرض الرئيسي."},"video":{"script":[{"time":"00:00–00:20","narration":"Why do authors write? Let's cut a PIE! Persuade, Inform, Entertain.","on_screen":"Author's Purpose PIE 🥧","visual":"A pie with three slices labelled P, I and E."},{"time":"00:20–00:55","narration":"Persuade: Drink water! Inform: Your heart is a muscle. Entertain: a funny story about a late alarm clock!","on_screen":"P · I · E examples","visual":"Each slice shows a quick example: a poster, a fact card, a storybook."},{"time":"00:55–01:55","narration":"Ibn Sina: The Young Doctor. More than 1,000 years ago, a boy named Ibn Sina lived near Bukhara…","on_screen":"(biography)","visual":"Respectful illustrated scenes: a boy reading, a young man helping the sick, the royal library, a huge old book."},{"time":"01:55–02:30","narration":"Clues: dates, numbers, true facts about a real person – the main purpose is to INFORM.","on_screen":"Clues → purpose","visual":"Clue words light up and drop into the 'Inform' slice."},{"time":"02:30–03:00","narration":"The last line inspires us: curiosity and hard work can help the whole world!","on_screen":"More than one purpose","visual":"A small arrow from the 'Inform' slice to a star labelled 'inspire'."}],"captions_ar":["لماذا يكتب الكُتّاب؟ لنقطّع فطيرة PIE: الإقناع والإعلام والإمتاع.","إقناع: اشرب الماء! إعلام: قلبك عضلة. إمتاع: قصة مضحكة عن منبّه متأخر!","ابن سينا: الطبيب الصغير. قبل أكثر من ألف عام عاش فتى اسمه ابن سينا قرب بخارى…","الأدلة: تواريخ وأرقام وحقائق عن شخص حقيقي؛ فالغرض الرئيسي هو الإعلام.","السطر الأخير يلهمنا: حب الاستطلاع والعمل الجاد يمكن أن يساعدا العالم كله!"],"voice":"Narrator: American English, warm female teacher, speed 0.90. Biography reader: calm, respectful male voice."},"texts":[{"type":"reading","title":"Ibn Sina: The Young Doctor","body":"More than 1,000 years ago, a boy named Ibn Sina lived near the city of Bukhara. He loved to read. By the age of ten, he had memorized the whole Quran!\n\nIbn Sina studied math, science and medicine. At sixteen, he was already helping sick people. When he was about seventeen, the ruler of Bukhara became very ill. Other doctors could not help him, but young Ibn Sina did! To thank him, the ruler let him read the books in the royal library.\n\nLater, Ibn Sina wrote a huge book about medicine called The Canon of Medicine. Doctors in many countries used it for hundreds of years.\n\nIbn Sina showed that curiosity and hard work can help the whole world.","word_count":121,"audio_id":"AUD-RW-L03-U4-LS3-T1","id":"TXT-RW-L03-U4-LS3-1","genre":"biography","role":"paired","difficulty":"350L–500L","glossary":[{"word":"memorized","definition":"learned by heart so you can say it without looking","arabic":"حفظ عن ظهر قلب"},{"word":"medicine","definition":"the study of how to keep people healthy and treat illness","arabic":"الطب"},{"word":"royal","definition":"belonging to a king or ruler","arabic":"ملكي"}]}],"activities":[{"id":"RW-L03-U4-LS3-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Read *Ibn Sina: The Young Doctor*. Choose the answer.","instructions_ar":"اقرأ السيرة واختر الإجابة.","items":[{"q":"Where did Ibn Sina live?","answer":"near the city of Bukhara","explanation":"Paragraph 1.","explanation_ar":"قرب بخارى.","options":["in Taif","near the city of Bukhara","in Canada","in Madinah"],"dok":1,"skill":"key details","text_id":"TXT-RW-L03-U4-LS3-1","stage":"controlled"},{"q":"What had Ibn Sina memorized by the age of ten?","answer":"the whole Quran","explanation":"Paragraph 1.","explanation_ar":"القرآن كله.","options":["a medicine book","a map of the world","a long poem","the whole Quran"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"How old was Ibn Sina when he was already helping sick people?","answer":"sixteen","explanation":"Paragraph 2.","explanation_ar":"ستة عشر.","options":["ten","thirty","five","sixteen"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"How did the ruler thank Ibn Sina?","answer":"He let him read the books in the royal library.","explanation":"Paragraph 2.","explanation_ar":"سمح له بقراءة كتب المكتبة الملكية.","options":["He gave him a camel.","He made him a king.","He let him read the books in the royal library.","He built him a hospital."],"dok":1,"skill":"key details","stage":"controlled"},{"q":"What was the name of Ibn Sina's huge book?","answer":"The Canon of Medicine","explanation":"Paragraph 3.","explanation_ar":"القانون في الطب.","options":["Your Busy Heart","The Royal Library","The Canon of Medicine","The Young Doctor"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"How long did doctors use Ibn Sina's book?","answer":"for hundreds of years","explanation":"Paragraph 3.","explanation_ar":"مئات السنين.","options":["for hundreds of years","for one week","for ten days","never"],"dok":1,"skill":"key details","stage":"controlled"}]},{"id":"RW-L03-U4-LS3-A2","type":"mcq","stage":"guided","instructions":"Guided practice: Author's purpose. Choose.","instructions_ar":"غرض الكاتب: اختر.","items":[{"q":"What is the MAIN purpose of *Ibn Sina: The Young Doctor*?","answer":"to inform","explanation":"True facts about a real person.","explanation_ar":"الإعلام.","options":["to persuade","to entertain","to inform","to sell a book"],"dok":1,"skill":"author's purpose","stage":"guided"},{"q":"Which clue shows the biography informs?","answer":"More than 1,000 years ago, a boy named Ibn Sina lived near the city of Bukhara.","explanation":"A dated fact.","explanation_ar":"حقيقة مؤرخة.","options":["Drink water instead of soda!","More than 1,000 years ago, a boy named Ibn Sina lived near the city of Bukhara.","Once upon a time, a funny cat…","Buy this book now!"],"dok":2,"skill":"clues","stage":"guided"},{"q":"*Brush your teeth twice a day – it is the best habit!* The purpose is to ___.","answer":"persuade","explanation":"It tells you what to do.","explanation_ar":"الإقناع.","options":["persuade","inform","entertain","describe a person"],"dok":1,"skill":"author's purpose","stage":"guided"},{"q":"A funny story about a cat who wears socks is mostly written to ___.","answer":"entertain","explanation":"Funny story → entertain.","explanation_ar":"الإمتاع.","options":["persuade","inform","teach medicine","entertain"],"dok":1,"skill":"author's purpose","stage":"guided"},{"q":"Which part of *Your Busy Heart* tries to PERSUADE?","answer":"Look After Your Heart","explanation":"Tips = persuade.","explanation_ar":"قسم النصائح.","options":["A Strong Pump","What Does Blood Carry?","the title","Look After Your Heart"],"dok":2,"skill":"author's purpose","stage":"guided"},{"q":"Why can *The Desert Fox at Night* have TWO purposes?","answer":"It entertains with rhyme and also informs with facts about the fox.","explanation":"Poem + facts.","explanation_ar":"يُمتع ويُعلِم.","options":["It is an advert.","It entertains with rhyme and also informs with facts about the fox.","It is a letter.","It has no facts."],"dok":3,"skill":"multiple purposes","stage":"guided"}]},{"id":"RW-L03-U4-LS3-A3","type":"organizer","stage":"freer","instructions":"Organizer: Complete the Author's Purpose PIE.","instructions_ar":"أكمل فطيرة غرض الكاتب.","items":[{"q":"*Your Busy Heart*: purpose + clue.","answer":"Inform – it gives facts like 'Your heart is a muscle about the size of your fist.' The last part also persuades with tips.","explanation":"Purpose + clue.","explanation_ar":"غرض + دليل.","dok":2,"skill":"author's purpose","stage":"freer"},{"q":"*Ibn Sina: The Young Doctor*: purpose + clue.","answer":"Inform – it tells true facts and dates about a real person.","explanation":"Purpose + clue.","explanation_ar":"غرض + دليل.","dok":2,"skill":"author's purpose","stage":"freer"},{"q":"*The Saturday Clean-Up*: purpose + clue.","answer":"Entertain – it has characters, a problem and a happy ending.","explanation":"Purpose + clue.","explanation_ar":"غرض + دليل.","dok":2,"skill":"author's purpose","stage":"freer"},{"q":"A poster *Wash your hands before you eat!*: purpose + clue.","answer":"Persuade – it tells us what we should do.","explanation":"Purpose + clue.","explanation_ar":"غرض + دليل.","dok":1,"skill":"author's purpose","stage":"freer"}]},{"id":"RW-L03-U4-LS3-A4","type":"open","stage":"production","instructions":"Writing: Think and write.","instructions_ar":"فكّر واكتب.","items":[{"q":"What lesson does the last sentence of the biography teach?","answer":"Curiosity and hard work can help the whole world.","explanation":"The message.","explanation_ar":"الرسالة.","dok":2,"skill":"theme","stage":"production"},{"q":"Which trait best describes Ibn Sina? Give evidence.","answer":"Hard-working, because he studied math, science and medicine and helped sick people at sixteen.","explanation":"Trait + evidence.","explanation_ar":"صفة + دليل.","dok":3,"skill":"character traits","stage":"production"},{"q":"Write one sentence to PERSUADE your classmates to read more.","answer":"You should read every day because books make your brain stronger!","explanation":"Persuade.","explanation_ar":"إقناع.","dok":2,"skill":"writing for purpose","stage":"production"},{"q":"Write one sentence to INFORM about the brain.","answer":"The brain is inside your head, and it controls your whole body.","explanation":"Inform.","explanation_ar":"إعلام.","dok":2,"skill":"writing for purpose","stage":"production"}]},{"id":"RW-L03-U4-LS3-TR-1","type":"timed_reading","instructions":"Timed reading: Read \"Ibn Sina: The Young Doctor\" aloud or silently. Try to finish in the time.","instructions_ar":"اقرأ النص وحاول أن تنهيه في الوقت المحدد.","items":[{"q":"Read “Ibn Sina: The Young Doctor”.","answer":"121 words","title":"Ibn Sina: The Young Doctor","body":"More than 1,000 years ago, a boy named Ibn Sina lived near the city of Bukhara. He loved to read. By the age of ten, he had memorized the whole Quran!\n\nIbn Sina studied math, science and medicine. At sixteen, he was already helping sick people. When he was about seventeen, the ruler of Bukhara became very ill. Other doctors could not help him, but young Ibn Sina did! To thank him, the ruler let him read the books in the royal library.\n\nLater, Ibn Sina wrote a huge book about medicine called The Canon of Medicine. Doctors in many countries used it for hundreds of years.\n\nIbn Sina showed that curiosity and hard work can help the whole world.","words":121,"limit":118}],"time_limit_sec":118},{"id":"RW-L03-U4-LS3-ORG","type":"organizer","organizer":"Author's Purpose PIE","instructions":"Organizer: For each text, choose the slice (Persuade, Inform or Entertain) and write one clue from the text.","items":[{"q":"Your Busy Heart – purpose + clue","answer":"Inform (also persuade at the end) – facts like 'Your heart beats about 100,000 times every day'; tips in the last section"},{"q":"Ibn Sina: The Young Doctor – purpose + clue","answer":"Inform – dates and true facts: 'More than 1,000 years ago…', 'wrote a huge book about medicine'"},{"q":"The Saturday Clean-Up (Unit 2) – purpose + clue","answer":"Entertain – characters, a problem (a dirty park) and a happy ending"},{"q":"A poster: 'Brush your teeth twice a day!' – purpose + clue","answer":"Persuade – it tells you what to do"}]}],"game":{"name":"Pick the PIE Slice","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: PIE sorter: short texts drop onto a pie; the child drags each one to Persuade, Inform or Entertain and taps the clue word. A full correct pie comes out of the oven golden.","Teams take turns drawing a text card.","The team reads it and places it on a slice.","The team must say the clue (facts, tips, characters…).","Other teams can challenge with a better clue.","Correct slice + clue = 2 points."],"data":[]},"exit_quiz":[{"q":"What does the *I* in PIE stand for?","answer":"Inform","explanation":"PIE = Persuade, Inform, Entertain.","explanation_ar":"Inform.","options":["Invent","Invite","Ill","Inform"],"dok":1,"skill":"author's purpose"},{"q":"An author who wants you to DO something is trying to ___.","answer":"persuade","explanation":"Persuade = make you do or think.","explanation_ar":"يقنعك.","options":["persuade","inform","entertain","memorize"],"dok":1,"skill":"author's purpose"},{"q":"A biography is ___.","answer":"the true story of a real person's life","explanation":"Biography = true life story.","explanation_ar":"سيرة حقيقية.","options":["a made-up funny story","a poem with rhyme","the true story of a real person's life","a list of steps"],"dok":1,"skill":"genre"},{"q":"*The ruler became very ill.* *Ill* means ___.","answer":"sick","explanation":"Ill = sick.","explanation_ar":"مريض.","options":["sick","happy","rich","tired of reading"],"dok":1,"skill":"vocabulary"},{"q":"Which sentence is written to ENTERTAIN?","answer":"The lazy lion slept so long that a bird built a nest on his head!","explanation":"Funny story = entertain.","explanation_ar":"للإمتاع.","options":["Lions live in Africa.","Visit the zoo this weekend!","A lion can sleep 20 hours a day.","The lazy lion slept so long that a bird built a nest on his head!"],"dok":2,"skill":"author's purpose"},{"q":"Which sentence about Ibn Sina is in the past tense?","answer":"Ibn Sina studied medicine.","explanation":"Biographies use the past.","explanation_ar":"studied.","options":["Ibn Sina studies medicine.","Ibn Sina will study medicine.","Ibn Sina studied medicine.","Ibn Sina studying medicine."],"dok":2,"skill":"grammar"},{"q":"*Curiosity helped Ibn Sina learn.* *Curiosity* means ___.","answer":"wanting to know and learn things","explanation":"Curiosity = wanting to know.","explanation_ar":"حب الاستطلاع.","options":["wanting to know and learn things","being very sleepy","being sick","being a ruler"],"dok":2,"skill":"vocabulary"},{"q":"Why did the author include the age *sixteen*?","answer":"to show how young Ibn Sina was when he helped sick people","explanation":"The number shows he was young.","explanation_ar":"ليُظهر صغر سنه.","options":["to tell a joke","to show how young Ibn Sina was when he helped sick people","to persuade you to buy medicine","to describe the library"],"dok":2,"skill":"author's craft"},{"q":"How are *Your Busy Heart* and the Ibn Sina biography alike?","answer":"Both inform readers about health or medicine.","explanation":"Both give facts about health.","explanation_ar":"كلاهما يُعلِم عن الصحة.","options":["Both are funny stories.","Both are letters.","Both inform readers about health or medicine.","Both are poems."],"dok":3,"skill":"compare texts"},{"q":"Why is it useful to know an author's purpose?","answer":"It helps you understand how to read the text and what the author wants from you.","explanation":"Purpose guides reading.","explanation_ar":"يساعدك على الفهم.","options":["It tells you the page number.","It helps you understand how to read the text and what the author wants from you.","It makes the text shorter.","It is only for poems."],"dok":3,"skill":"strategy"}],"images":[{"id":"IMG-RW-L03-U4-LS3-V01","prompt":"Picture for the word 'biography': a book with a portrait on the cover"},{"id":"IMG-RW-L03-U4-LS3-V02","prompt":"Picture for the word 'medicine': an old book with plant drawings and a stethoscope"},{"id":"IMG-RW-L03-U4-LS3-V03","prompt":"Picture for the word 'ruler': a ruler on a carved chair"},{"id":"IMG-RW-L03-U4-LS3-V04","prompt":"Picture for the word 'ill': a man in bed with a cloth on his forehead"},{"id":"IMG-RW-L03-U4-LS3-V05","prompt":"Picture for the word 'memorize': a boy reciting with eyes closed and an open Quran beside him"},{"id":"IMG-RW-L03-U4-LS3-V06","prompt":"Picture for the word 'curiosity': a child looking through a magnifying glass at a leaf"},{"id":"IMG-RW-L03-U4-LS3-V07","prompt":"Picture for the word 'entertain': children laughing at a puppet show"},{"id":"IMG-RW-L03-U4-LS3-01","prompt":"A young scholar reading in a royal library."},{"id":"IMG-RW-L03-U4-LS3-02","prompt":"A pie organizer for persuade, inform and entertain."},{"id":"IMG-RW-L03-U4-LS3-03","prompt":"A poster, a fact card and a storybook."}],"audio":[{"id":"AUD-RW-L03-U4-LS3-V01","script":"biography. We read a biography of Ibn Sina."},{"id":"AUD-RW-L03-U4-LS3-V02","script":"medicine. Ibn Sina studied medicine."},{"id":"AUD-RW-L03-U4-LS3-V03","script":"ruler. The ruler of Bukhara was ill."},{"id":"AUD-RW-L03-U4-LS3-V04","script":"ill. The ruler became very ill."},{"id":"AUD-RW-L03-U4-LS3-V05","script":"memorize. He memorized the whole Quran."},{"id":"AUD-RW-L03-U4-LS3-V06","script":"curiosity. Curiosity helped Ibn Sina learn."},{"id":"AUD-RW-L03-U4-LS3-V07","script":"entertain. Funny stories entertain us."},{"id":"AUD-RW-L03-U4-LS3-T1","script":"More than 1,000 years ago, a boy named Ibn Sina lived near the city of Bukhara. He loved to read. By the age of ten, he had memorized the whole Quran! Ibn Sina studied math, science and medicine. At sixteen, he was already helping sick people. When he was about seventeen, the ruler of Bukhara became very ill. Other doctors could not help him, but young Ibn Sina did! To thank him, the ruler let him read the books in the royal library. Later, Ibn Sina wrote a huge book about medicine called The Canon of Medicine. Doctors in many countries used it for hundreds of years. Ibn Sina showed that curiosity and hard work can help the whole world."},{"id":"AUD-RW-L03-U4-LS3-VID","script":"Why do authors write? Let's cut a PIE! Persuade, Inform, Entertain. Persuade: Drink water! Inform: Your heart is a muscle. Entertain: a funny story about a late alarm clock! Ibn Sina: The Young Doctor. More than 1,000 years ago, a boy named Ibn Sina lived near Bukhara… Clues: dates, numbers, true facts about a real person – the main purpose is to INFORM. The last line inspires us: curiosity and hard work can help the whole world!"}]},{"id":"RW-L03-U4-LS4","title":"Writing Skill: Adding facts and examples","lesson_type":"writing_skill","objectives":["support details with facts (true information, often with numbers) and examples","introduce examples with for example, and such as","tell a fact from an example and from an opinion"],"objectives_ar":["دعم التفاصيل بحقائق (معلومات صحيحة غالبًا بأرقام) وأمثلة.","تقديم الأمثلة بـ for example و such as.","التمييز بين الحقيقة والمثال والرأي."],"success_criteria":["I can add a fact to support a detail.","I can add an example with For example, or such as.","I can punctuate For example, correctly."],"success_criteria_ar":["أستطيع إضافة حقيقة لدعم تفصيل.","أستطيع إضافة مثال بـ For example أو such as.","أستطيع ترقيم For example بشكل صحيح."],"map_area":"Language Usage: Write, Revise Texts for Purpose and Audience (cross-strand)","vocabulary":[{"word":"fact","pos":"noun","ipa":"/fækt/","definition":"something that is true and can be checked","arabic":"حقيقة","example":"It is a fact that the heart is a muscle.","image_id":"IMG-RW-L03-U4-LS4-V01","audio_id":"AUD-RW-L03-U4-LS4-V01","tier":"core"},{"word":"example","pos":"noun","ipa":"/ɪɡˈzæmpəl/","definition":"one thing that shows what you mean","arabic":"مثال","example":"Apples are an example of a healthy snack.","image_id":"IMG-RW-L03-U4-LS4-V02","audio_id":"AUD-RW-L03-U4-LS4-V02","tier":"core"},{"word":"for example","pos":"phrase","ipa":"/fɔr ɪɡˈzæmpəl/","definition":"words that start an example","arabic":"على سبيل المثال","example":"For example, I walk to the mosque every day.","image_id":"IMG-RW-L03-U4-LS4-V03","audio_id":"AUD-RW-L03-U4-LS4-V03","tier":"core"},{"word":"such as","pos":"phrase","ipa":"/sʌtʃ æz/","definition":"words that give examples inside a sentence","arabic":"مثل","example":"Eat fruit such as dates and oranges.","image_id":"IMG-RW-L03-U4-LS4-V04","audio_id":"AUD-RW-L03-U4-LS4-V04","tier":"core"},{"word":"repair","pos":"verb","ipa":"/rɪˈpɛr/","definition":"to fix something that is broken or tired","arabic":"يُصلح / يرمّم","example":"Your body repairs muscles while you sleep.","image_id":"IMG-RW-L03-U4-LS4-V05","audio_id":"AUD-RW-L03-U4-LS4-V05","tier":"core"},{"word":"superpower","pos":"noun","ipa":"/ˈsupərpaʊər/","definition":"a special, amazing power","arabic":"قوة خارقة","example":"Sleep is like a superpower.","image_id":"IMG-RW-L03-U4-LS4-V06","audio_id":"AUD-RW-L03-U4-LS4-V06","tier":"core"},{"word":"support","pos":"verb","ipa":"/səˈpɔrt/","definition":"to give facts or examples that show an idea is true","arabic":"يدعم","example":"Support your detail with a fact.","image_id":"IMG-RW-L03-U4-LS4-V07","audio_id":"AUD-RW-L03-U4-LS4-V07","tier":"core"}],"explanation":{"text":"Strong informative writing does not just say an idea – it **proves** it. Support each detail with a **fact** or an **example**.\n\nA **fact** is **true** and can be **checked** (often with a number): *Children need about ten hours of sleep.* An **example** shows the idea **in real life**: *For example, my brother remembered ten new words after a good sleep.*\n\nUse **For example,** (with a comma) at the **start** of a new sentence. Use **such as** to give examples **inside** a sentence: *Eat fruit **such as** dates and oranges.*","examples":["Detail: **Exercise is good for your heart.**","+ Fact: **Children should move and play for one hour every day.**","+ Example: **For example, I ride my bicycle to the park after school.**","Detail: **Some foods help your bones grow.**","+ such as: **Foods such as milk, cheese and yogurt make your bones strong.**","Detail: **Water is important for your body.**","+ Fact: **More than half of your body is water.**","+ Example: **For example, I drink a glass of water after every break.**","Not a fact (opinion): *Milk is the most delicious drink.* → keep opinions out of informative paragraphs."],"common_errors":["✗ For example I ride my bike. → ✓ For example, I ride my bike. (Comma after **For example**.)","✗ Eat fruit such as, dates. → ✓ Eat fruit such as dates. (No comma right after **such as**.)","✗ For example dates and oranges. (no sentence) → ✓ For example, dates and oranges are healthy snacks. (After **For example,** write a full sentence.)","✗ Fact: Soda is yucky. → ✓ Fact: Soda has a lot of sugar. (A fact can be **checked**; 'yucky' is an opinion.)","✗ An example that does not match: 'Sleep helps your brain. For example, I like pizza.' → ✓ For example, I remember my spelling words better after a good sleep. (The example must **show** the detail.)","✗ Children needs ten hours of sleep. → ✓ Children need about ten hours of sleep. (Children (many) → **need**.)"],"arabic":"الكتابة المعلوماتية القوية لا تكتفي بذكر الفكرة بل تُثبتها، فادعم كل تفصيل بحقيقة أو مثال.\n\nالحقيقة صحيحة ويمكن التحقق منها (غالبًا برقم)، والمثال يُظهر الفكرة في الحياة الواقعية.\n\nاستخدم For example, مع فاصلة في بداية جملة جديدة، واستخدم such as لإعطاء أمثلة داخل الجملة نفسها.\n\nالرأي (مثل: الحليب ألذ مشروب) لا يوضع في الفقرة المعلوماتية."},"video":{"script":[{"time":"00:00–00:20","narration":"Noura says sleep is a superpower! Can she prove it?","on_screen":"Sleep Is a Superpower 😴🦸","visual":"Noura holds a pillow like a shield; a cape flutters."},{"time":"00:20–01:05","narration":"Sleep helps every part of your body. First, sleep helps your brain…","on_screen":"(model paragraph)","visual":"Each sentence appears; facts glow blue, examples glow coral."},{"time":"01:05–01:40","narration":"A fact is true and can be checked – often with a number: about ten hours a night!","on_screen":"Fact ✔ = can be checked","visual":"A magnifying glass checks the number '10 hours'."},{"time":"01:40–02:20","narration":"An example shows it in real life: For example, my brother learned ten new words! Such as gives examples inside a sentence.","on_screen":"For example, …  ·  such as …","visual":"A comma pops after 'For example'; 'such as' links to a picture of leg muscles."},{"time":"02:20–03:00","narration":"Prove your ideas: add a fact, add an example!","on_screen":"Detail + fact + example","visual":"A detail block gets two support pillars: 'fact' and 'example'."}],"captions_ar":["تقول نورة إن النوم قوة خارقة! هل تستطيع أن تُثبت ذلك؟","النوم يساعد كل جزء من جسمك. أولًا: النوم يساعد دماغك…","الحقيقة صحيحة ويمكن التحقق منها، وغالبًا برقم: نحو عشر ساعات كل ليلة!","المثال يُظهرها في الواقع: For example… وsuch as تعطي أمثلة داخل الجملة.","أثبت أفكارك: أضف حقيقة، وأضف مثالًا!"],"voice":"Narrator: American English, warm female teacher, speed 0.90. Noura reads her paragraph in a lively voice."},"texts":[{"type":"model","title":"Sleep Is a Superpower (by Noura)","body":"Sleep helps every part of your body. First, sleep helps your brain. Children who sleep about ten hours a night can remember new words better. For example, my brother learned ten new spelling words before bed, and in the morning he still knew all of them! Also, sleep helps your muscles grow strong. While you sleep, your body repairs tired muscles, such as the muscles in your legs after football. In addition, sleep keeps you healthy, so you get sick less often. That is why sleep is like a superpower for your body.","word_count":93,"audio_id":"AUD-RW-L03-U4-LS4-T1","id":"TXT-RW-L03-U4-LS4-1","genre":"model text","role":"model","difficulty":"350L–500L","glossary":[],"annotations":["**Sleep helps every part of your body.** – the topic sentence.","**Children who sleep about ten hours a night can remember new words better.** – a **fact** with a **number**.","**For example, my brother learned ten new spelling words…** – an **example** that shows the fact in real life. *For example* has a comma after it.","**such as the muscles in your legs after football** – **such as** gives an example **inside** the same sentence (no comma needed after it).","**Also, … In addition, …** – linking words that add more details.","**That is why sleep is like a superpower for your body.** – the closing sentence."]}],"activities":[{"id":"RW-L03-U4-LS4-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Choose the best answer.","instructions_ar":"اختر أفضل إجابة.","items":[{"q":"Which sentence in Noura's paragraph is a FACT with a number?","answer":"Children who sleep about ten hours a night can remember new words better.","explanation":"A number + checkable.","explanation_ar":"حقيقة برقم.","options":["Children who sleep about ten hours a night can remember new words better.","That is why sleep is like a superpower.","Sleep helps every part of your body.","Also, sleep helps your muscles grow strong."],"dok":2,"skill":"facts","stage":"controlled"},{"q":"Which words start Noura's example about her brother?","answer":"For example,","explanation":"For example, my brother…","explanation_ar":"For example.","options":["In addition,","For example,","That is why","Also,"],"dok":1,"skill":"examples","stage":"controlled"},{"q":"A sentence that is true and can be checked is a ___.","answer":"fact","explanation":"Fact = true, can be checked.","explanation_ar":"حقيقة.","options":["opinion","fact","closing","title"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"*Your body repairs tired muscles.* *Repairs* means ___.","answer":"fixes","explanation":"Repair = fix.","explanation_ar":"يُصلح.","options":["breaks","hides","fixes","eats"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"Which phrase gives examples INSIDE a sentence?","answer":"such as","explanation":"such as = inside the sentence.","explanation_ar":"such as.","options":["For example,","Finally,","First,","such as"],"dok":1,"skill":"such as","stage":"controlled"},{"q":"Which sentence about leg muscles uses *such as* correctly?","answer":"Exercise helps muscles such as the muscles in your legs.","explanation":"No comma after such as.","explanation_ar":"صحيحة.","options":["Exercise helps muscles, such as, the legs.","Exercise helps muscles such, as legs.","Exercise helps muscles such as the muscles in your legs.","Such as exercise helps muscles."],"dok":2,"skill":"punctuation","stage":"controlled"}]},{"id":"RW-L03-U4-LS4-A2","type":"mcq","stage":"guided","instructions":"Guided practice: Fact, example or opinion? Choose.","instructions_ar":"حقيقة أم مثال أم رأي؟ اختر.","items":[{"q":"*Your heart beats about 100,000 times a day.* This is ___.","answer":"a fact","explanation":"It can be checked.","explanation_ar":"حقيقة.","options":["an opinion","an example","a question","a fact"],"dok":1,"skill":"fact vs. opinion","stage":"guided"},{"q":"*Football is the best sport in the world.* This is ___.","answer":"an opinion","explanation":"'the best' = what someone thinks.","explanation_ar":"رأي.","options":["a fact","an example","a definition","an opinion"],"dok":1,"skill":"fact vs. opinion","stage":"guided"},{"q":"*For example, I walk to the mosque with my father every evening.* This is ___.","answer":"an example","explanation":"It shows a habit in real life.","explanation_ar":"مثال.","options":["an example","an opinion","a heading","a closing"],"dok":1,"skill":"examples","stage":"guided"},{"q":"Which example BEST supports *Drinking water helps you think*?","answer":"For example, I can focus better in class after I drink water.","explanation":"It shows the detail in real life.","explanation_ar":"يدعم التفصيل.","options":["For example, I can focus better in class after I drink water.","For example, I like orange juice.","For example, camels drink a lot.","For example, water is wet."],"dok":2,"skill":"relevant examples","stage":"guided"},{"q":"Which fact BEST supports *Milk helps your bones*?","answer":"Milk has calcium, which helps bones grow strong.","explanation":"A checkable fact about bones.","explanation_ar":"حقيقة داعمة.","options":["Milk is white.","Milk has calcium, which helps bones grow strong.","I drink milk at breakfast.","Milk is the tastiest drink."],"dok":2,"skill":"relevant facts","stage":"guided"},{"q":"Which sentence uses *For example* correctly?","answer":"For example, I brush my teeth after every meal.","explanation":"For example + comma + sentence.","explanation_ar":"صحيحة.","options":["For example I brush my teeth after every meal.","For, example I brush my teeth.","For example, I brush my teeth after every meal.","I brush for example, my teeth."],"dok":2,"skill":"punctuation","stage":"guided"}]},{"id":"RW-L03-U4-LS4-A3","type":"gap_fill","stage":"freer","instructions":"Freer practice: Use the word bank.","instructions_ar":"استخدم بنك الكلمات.","items":[{"q":"________, I eat an apple every day at school.","answer":"For example","explanation":"Starts an example sentence.","explanation_ar":"على سبيل المثال.","stage":"freer"},{"q":"Eat vegetables ________ carrots and cucumbers.","answer":"such as","explanation":"Examples inside the sentence.","explanation_ar":"مثل.","stage":"freer"},{"q":"It is a ________ that teeth are covered in enamel.","answer":"fact","explanation":"True and can be checked.","explanation_ar":"حقيقة.","stage":"freer"},{"q":"Your body can ________ small cuts on your skin.","answer":"repair","explanation":"Fix.","explanation_ar":"يُصلح.","stage":"freer"},{"q":"Good writers ________ their ideas with facts and examples.","answer":"support","explanation":"Show they are true.","explanation_ar":"يدعمون.","stage":"freer"},{"q":"Riding my bicycle is one ________ of exercise.","answer":"example","explanation":"One thing that shows the idea.","explanation_ar":"مثال.","stage":"freer"}]},{"id":"RW-L03-U4-LS4-A4","type":"open","stage":"production","instructions":"Writing: Add facts and examples.","instructions_ar":"أضف حقائق وأمثلة.","items":[{"q":"Add a fact to this detail: *Exercise is good for your heart.*","answer":"Children should move and play for one hour every day.","explanation":"A checkable fact.","explanation_ar":"حقيقة يمكن التحقق منها.","dok":2,"skill":"facts","stage":"production"},{"q":"Add an example with *For example,* to the same detail.","answer":"For example, I play football with my cousins after school.","explanation":"Example sentence.","explanation_ar":"جملة مثال.","dok":2,"skill":"examples","stage":"production"},{"q":"Write a sentence about healthy snacks with *such as*.","answer":"Healthy snacks such as dates, apples and nuts give you energy.","explanation":"such as + examples.","explanation_ar":"such as + أمثلة.","dok":2,"skill":"such as","stage":"production"},{"q":"Change this opinion into a fact: *Sleep is the best thing ever.*","answer":"Children need about ten hours of sleep every night.","explanation":"Opinion → fact.","explanation_ar":"رأي ← حقيقة.","dok":3,"skill":"fact vs. opinion","stage":"production"}]}],"game":{"name":"Fact, Example or Opinion?","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Sorting station: health sentences slide on a conveyor belt; the child drops each into Fact, Example or Opinion. Correct sorts fill a health meter.","Teams take turns drawing a card and reading it aloud.","The team chooses a box and gives a reason (can be checked / shows real life / someone's feeling).","Other teams can challenge.","Correct box + reason = 2 points.","Bonus: change an opinion card into a fact."],"data":[]},"exit_quiz":[{"q":"Why do writers add facts and examples?","answer":"to support and prove their ideas","explanation":"Support ideas.","explanation_ar":"لدعم أفكارهم وإثباتها.","options":["to make the paragraph confusing","to tell a story","to support and prove their ideas","to end the paragraph"],"dok":1,"skill":"purpose"},{"q":"Which phrase starts an example sentence?","answer":"For example,","explanation":"For example.","explanation_ar":"For example.","options":["For example,","Finally,","Dear Hamza,","In 1908,"],"dok":1,"skill":"examples"},{"q":"An opinion is ___.","answer":"what someone thinks or feels","explanation":"Opinion = thinks/feels.","explanation_ar":"ما يعتقده الشخص.","options":["a true fact","a number","what someone thinks or feels","a heading"],"dok":1,"skill":"fact vs. opinion"},{"q":"*Eat fruit such as dates and bananas.* *Such as* introduces ___.","answer":"examples","explanation":"such as = examples.","explanation_ar":"أمثلة.","options":["a closing","a question","a date","examples"],"dok":1,"skill":"such as"},{"q":"Which sentence about sleep is a FACT?","answer":"Sleep helps the body repair tired muscles.","explanation":"Checkable.","explanation_ar":"حقيقة.","options":["Sleeping is boring.","Bedtime is the worst time.","My pillow is the best.","Sleep helps the body repair tired muscles."],"dok":2,"skill":"fact vs. opinion"},{"q":"Fix it: *For example I drink water after football.*","answer":"For example, I drink water after football.","explanation":"Comma after For example.","explanation_ar":"فاصلة بعد For example.","options":["For, example I drink water after football.","For example, I drink water after football.","For example I, drink water after football.","For example I drink water, after football."],"dok":2,"skill":"punctuation"},{"q":"Which example does NOT support *Exercise makes you strong*?","answer":"For example, I like chocolate cake.","explanation":"Cake does not show exercise.","explanation_ar":"لا يدعم الفكرة.","options":["For example, I like chocolate cake.","For example, I can carry heavier bags since I started swimming.","For example, my legs got stronger from running.","For example, I can do more push-ups now."],"dok":2,"skill":"relevant examples"},{"q":"*Children who sleep about ten hours remember better.* Why does the writer use *about*?","answer":"because the number is not exact for everyone","explanation":"About = approximately.","explanation_ar":"لأن الرقم تقريبي.","options":["because the writer is not sure what sleep is","to make it an opinion","to start an example","because the number is not exact for everyone"],"dok":3,"skill":"precise language"},{"q":"Which detail is BEST supported?","answer":"Water helps your body. More than half of your body is water. For example, I feel tired when I forget to drink.","explanation":"Detail + fact + example.","explanation_ar":"مدعوم بحقيقة ومثال.","options":["Water helps your body.","Water helps your body. More than half of your body is water. For example, I feel tired when I forget to drink.","Water helps your body. I like juice.","Water. Water. Water."],"dok":3,"skill":"evaluate"},{"q":"Noura says sleep is *like a superpower*. What does she mean?","answer":"Sleep gives your body amazing help.","explanation":"A comparison for effect.","explanation_ar":"النوم يمنح الجسم مساعدة مدهشة.","options":["Sleep lets you fly.","Sleep is a movie.","Sleep gives your body amazing help.","Sleep is not important."],"dok":2,"skill":"figurative language"}],"images":[{"id":"IMG-RW-L03-U4-LS4-V01","prompt":"Picture for the word 'fact': a checkmark next to a sentence"},{"id":"IMG-RW-L03-U4-LS4-V02","prompt":"Picture for the word 'example': a finger pointing to one apple in a basket"},{"id":"IMG-RW-L03-U4-LS4-V03","prompt":"Picture for the word 'for example': a speech bubble with 'For example…'"},{"id":"IMG-RW-L03-U4-LS4-V04","prompt":"Picture for the word 'such as': dates and oranges in a bowl"},{"id":"IMG-RW-L03-U4-LS4-V05","prompt":"Picture for the word 'repair': a cartoon wrench fixing a muscle"},{"id":"IMG-RW-L03-U4-LS4-V06","prompt":"Picture for the word 'superpower': a child in a cape asleep on a pillow"},{"id":"IMG-RW-L03-U4-LS4-V07","prompt":"Picture for the word 'support': pillars holding up a sign"},{"id":"IMG-RW-L03-U4-LS4-01","prompt":"Faris sleeps with a cape on his bed, dreaming of words and football."},{"id":"IMG-RW-L03-U4-LS4-02","prompt":"A detail held up by a fact pillar and an example pillar."},{"id":"IMG-RW-L03-U4-LS4-03","prompt":"Sentence cards sorted into fact, example and opinion boxes."}],"audio":[{"id":"AUD-RW-L03-U4-LS4-V01","script":"fact. It is a fact that the heart is a muscle."},{"id":"AUD-RW-L03-U4-LS4-V02","script":"example. Apples are an example of a healthy snack."},{"id":"AUD-RW-L03-U4-LS4-V03","script":"for example. For example, I walk to the mosque every day."},{"id":"AUD-RW-L03-U4-LS4-V04","script":"such as. Eat fruit such as dates and oranges."},{"id":"AUD-RW-L03-U4-LS4-V05","script":"repair. Your body repairs muscles while you sleep."},{"id":"AUD-RW-L03-U4-LS4-V06","script":"superpower. Sleep is like a superpower."},{"id":"AUD-RW-L03-U4-LS4-V07","script":"support. Support your detail with a fact."},{"id":"AUD-RW-L03-U4-LS4-T1","script":"Sleep helps every part of your body. First, sleep helps your brain. Children who sleep about ten hours a night can remember new words better. For example, my brother learned ten new spelling words before bed, and in the morning he still knew all of them! Also, sleep helps your muscles grow strong. While you sleep, your body repairs tired muscles, such as the muscles in your legs after football. In addition, sleep keeps you healthy, so you get sick less often. That is why sleep is like a superpower for your body."},{"id":"AUD-RW-L03-U4-LS4-VID","script":"Noura says sleep is a superpower! Can she prove it? Sleep helps every part of your body. First, sleep helps your brain… A fact is true and can be checked – often with a number: about ten hours a night! An example shows it in real life: For example, my brother learned ten new words! Such as gives examples inside a sentence. Prove your ideas: add a fact, add an example!"}]},{"id":"RW-L03-U4-LS5","title":"Writing Workshop: How to Keep My Heart Healthy","lesson_type":"writing_workshop","objectives":["plan an informative paragraph about keeping the heart healthy with a Hamburger Plan","write 6–8 sentences: a topic sentence, three healthy habits each supported by a fact or example, and a closing","revise to add support, edit and publish the paragraph as a 'Healthy Heart' leaflet"],"objectives_ar":["التخطيط لفقرة معلوماتية عن الحفاظ على صحة القلب بخطة الهامبرغر.","كتابة 6–8 جمل: جملة رئيسية، وثلاث عادات صحية يدعم كلًّا منها حقيقة أو مثال، وجملة ختامية.","التحسين بإضافة الدعم، والتدقيق، والنشر في مطوية «قلب صحي»."],"success_criteria":["I can write a topic sentence about keeping the heart healthy.","I can support each habit with a fact or an example.","I can use unit words and linking words correctly."],"success_criteria_ar":["أستطيع كتابة جملة رئيسية عن الحفاظ على صحة القلب.","أستطيع دعم كل عادة بحقيقة أو مثال.","أستطيع استخدام كلمات الوحدة وكلمات الربط بشكل صحيح."],"map_area":"Language Usage: Write, Revise Texts for Purpose and Audience (cross-strand)","vocabulary":[{"word":"healthy","pos":"adjective","ipa":"/ˈhɛlθi/","definition":"good for your body; not sick","arabic":"صحي","example":"Fruit is a healthy snack.","image_id":"IMG-RW-L03-U4-LS5-V01","audio_id":"AUD-RW-L03-U4-LS5-V01","tier":"core"},{"word":"habit","pos":"noun","ipa":"/ˈhæbɪt/","definition":"something you do often, again and again","arabic":"عادة","example":"Walking every day is a good habit.","image_id":"IMG-RW-L03-U4-LS5-V02","audio_id":"AUD-RW-L03-U4-LS5-V02","tier":"core"},{"word":"vegetables","pos":"noun","ipa":"/ˈvɛdʒtəbəlz/","definition":"plants or parts of plants we eat, like carrots and cucumbers","arabic":"خضراوات","example":"Eat vegetables at every meal.","image_id":"IMG-RW-L03-U4-LS5-V03","audio_id":"AUD-RW-L03-U4-LS5-V03","tier":"core"},{"word":"sugar","pos":"noun","ipa":"/ˈʃʊɡər/","definition":"something sweet in candy, soda and cakes","arabic":"سكر","example":"Soda has a lot of sugar.","image_id":"IMG-RW-L03-U4-LS5-V04","audio_id":"AUD-RW-L03-U4-LS5-V04","tier":"core"},{"word":"leaflet","pos":"noun","ipa":"/ˈliflɪt/","definition":"a small printed paper that gives information","arabic":"مطوية / نشرة","example":"We made a leaflet about healthy hearts.","image_id":"IMG-RW-L03-U4-LS5-V05","audio_id":"AUD-RW-L03-U4-LS5-V05","tier":"core"},{"word":"instead of","pos":"phrase","ipa":"/ɪnˈstɛd əv/","definition":"in the place of","arabic":"بدلًا من","example":"Drink water instead of soda.","image_id":"IMG-RW-L03-U4-LS5-V06","audio_id":"AUD-RW-L03-U4-LS5-V06","tier":"core"},{"word":"active","pos":"adjective","ipa":"/ˈæktɪv/","definition":"moving a lot; doing things","arabic":"نشيط","example":"Active children have strong hearts.","image_id":"IMG-RW-L03-U4-LS5-V07","audio_id":"AUD-RW-L03-U4-LS5-V07","tier":"core"}],"explanation":{"text":"Your paragraph will **inform** readers how to keep their hearts healthy. Choose **three healthy habits** (exercise, healthy food, water, sleep, less screen time).\n\nPlan with the **Hamburger Plan**: **topic sentence** → **habit 1 + fact or example** → **habit 2 + fact or example** → **habit 3 + fact or example** → **closing**.\n\nUse **linking words** (First, Also, In addition, That is why), **For example,** and **such as**, and **unit words** (heart, blood, muscles, exercise, oxygen). Write **facts**, not opinions, in the details.","examples":["Topic sentence: **There are three easy ways to keep your heart healthy.**","Habit 1: **First, be active for one hour every day.**","Support: **For example, you can play football, swim or ride a bicycle.**","Habit 2: **Also, eat healthy food such as fruit, vegetables and fish.**","Support (fact): **These foods give your body energy without too much sugar.**","Habit 3: **In addition, drink water instead of soda.**","Support (fact): **Soda has a lot of sugar, but water has none.**","Closing: **That is why these simple habits help your heart work hard for your whole life.**","Other habits: sleep about ten hours a night; spend less time on screens; walk instead of using the car for short trips."],"common_errors":["✗ Listing habits with no support. → ✓ First, be active every day. For example, you can play football. (Add a **fact** or **example** to each habit.)","✗ Soda is disgusting. → ✓ Soda has a lot of sugar. (Use **facts**, not opinions.)","✗ Eat healthy food such as, fruit. → ✓ Eat healthy food such as fruit. (No comma after **such as**.)","✗ Exercise make your heart strong. → ✓ Exercise makes your heart strong. (Exercise (one thing) → **makes**.)","✗ You should exercise your heart healthy. → ✓ You should exercise to keep your heart healthy. (Use **to + verb** for a reason.)","✗ (no closing) → ✓ That is why these habits help your heart. (End with a closing sentence.)"],"arabic":"فقرتك ستُعلِم القرّاء كيف يحافظون على صحة قلوبهم. اختر ثلاث عادات صحية (الرياضة، الطعام الصحي، الماء، النوم، تقليل الشاشات).\n\nخطّط بخطة الهامبرغر: الجملة الرئيسية ← العادة 1 + حقيقة أو مثال ← العادة 2 + حقيقة أو مثال ← العادة 3 + حقيقة أو مثال ← الخاتمة.\n\nاستخدم كلمات الربط وFor example وsuch as وكلمات الوحدة، واكتب حقائق لا آراء في التفاصيل.\n\nلا تذكر أسماء زملائك أو أوزانهم أو صحتهم في الكتابة؛ اجعلها نصائح عامة."},"video":{"script":[{"time":"00:00–00:20","narration":"Coach Omar has three tips for a healthy heart!","on_screen":"How to Keep My Heart Healthy ❤️","visual":"Omar with a whistle and a clipboard in the school yard."},{"time":"00:20–00:55","narration":"Plan with a hamburger: topic sentence, three habits with support, a closing!","on_screen":"1 Plan – Hamburger","visual":"Burger layers labelled habit + fact/example."},{"time":"00:55–01:55","narration":"There are three easy ways to keep your heart healthy. First, be active for one hour every day. For example…","on_screen":"2 Draft – habits + support","visual":"Icons: a football, a plate of fruit and vegetables, a water bottle."},{"time":"01:55–02:20","narration":"Revise: every habit needs a fact or an example! 'Soda is disgusting' – opinion! Change it to a fact.","on_screen":"3 Revise – facts, not opinions","visual":"An opinion sentence turns into a fact sentence."},{"time":"02:20–02:40","narration":"Edit: For example, (comma) · such as (no comma) · makes/make.","on_screen":"4 Edit , such as -s","visual":"Commas hop in and out of place."},{"time":"02:40–03:00","narration":"Publish: Omar's 'Healthy Heart' leaflet goes to every class!","on_screen":"5 Publish 📄","visual":"Children hand out folded leaflets in the corridor."}],"captions_ar":["المدرب عمر لديه ثلاث نصائح لقلب صحي!","خطّط بالهامبرغر: جملة رئيسية، وثلاث عادات مع الدعم، وخاتمة!","هناك ثلاث طرق سهلة للحفاظ على صحة قلبك. أولًا: كن نشيطًا ساعة كل يوم. على سبيل المثال…","التحسين: كل عادة تحتاج إلى حقيقة أو مثال! «المشروبات الغازية مقززة» رأي! حوّله إلى حقيقة.","التدقيق: For example مع فاصلة، وsuch as دون فاصلة، وmakes/make.","النشر: مطوية عمر «قلب صحي» تصل إلى كل الفصول!"],"voice":"Narrator: American English, warm female teacher, speed 0.90. Omar (the Reporter, sporty) reads his paragraph like a sports coach."},"texts":[],"activities":[{"id":"RW-L03-U4-LS5-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Choose the best answer.","instructions_ar":"اختر أفضل إجابة.","items":[{"q":"Which is the best topic sentence for *How to Keep My Heart Healthy*?","answer":"There are three easy ways to keep your heart healthy.","explanation":"It tells the main idea.","explanation_ar":"جملة رئيسية مناسبة.","options":["I love hearts.","Soda is sweet.","There are three easy ways to keep your heart healthy.","Hearts."],"dok":1,"skill":"topic sentence","stage":"controlled"},{"q":"Something you do again and again is a ___.","answer":"habit","explanation":"Habit = done often.","explanation_ar":"عادة.","options":["leaflet","habit","sugar","vegetable"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"Carrots, cucumbers and tomatoes are ___.","answer":"vegetables","explanation":"They are vegetables.","explanation_ar":"خضراوات.","options":["drinks","vegetables","habits","muscles"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"*Drink water instead of soda.* *Instead of* means ___.","answer":"in the place of","explanation":"Instead of = in the place of.","explanation_ar":"بدلًا من.","options":["in the place of","together with","after","before"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"A small printed paper that gives information is a ___.","answer":"leaflet","explanation":"Leaflet.","explanation_ar":"مطوية.","options":["leaflet","habit","fist","pump"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"Which habit is supported by a FACT?","answer":"Drink water instead of soda, because soda has a lot of sugar.","explanation":"Sugar in soda is a checkable fact.","explanation_ar":"مدعومة بحقيقة.","options":["Drink water because I said so.","Drink water. It is cool.","Drink water, water, water.","Drink water instead of soda, because soda has a lot of sugar."],"dok":2,"skill":"support","stage":"controlled"}]},{"id":"RW-L03-U4-LS5-A2","type":"sequence","stage":"guided","instructions":"Put in order: Put the paragraph or sentence in order.","instructions_ar":"رتّب الفقرة أو الجملة.","items":[{"q":"Order Omar's healthy-heart paragraph.","answer":"There are three easy ways to keep your heart healthy. → First, be active for one hour every day. → Also, eat fruit and vegetables. → In addition, drink water instead of soda. → That is why these habits help your heart.","explanation":"Topic → 3 habits → closing.","explanation_ar":"رئيسية ← 3 عادات ← خاتمة.","stage":"guided","parts":["In addition, drink water instead of soda.","That is why these habits help your heart.","Also, eat fruit and vegetables.","First, be active for one hour every day.","There are three easy ways to keep your heart healthy."],"target":["There are three easy ways to keep your heart healthy.","First, be active for one hour every day.","Also, eat fruit and vegetables.","In addition, drink water instead of soda.","That is why these habits help your heart."]},{"q":"Build an example sentence about being active.","answer":"For example, → you can → ride a bicycle.","explanation":"For example + comma + sentence.","explanation_ar":"For example + فاصلة + جملة.","stage":"guided","parts":["ride a bicycle.","For example,","you can"],"target":["For example,","you can","ride a bicycle."]},{"q":"Build a such-as sentence about food.","answer":"Eat healthy food → such as → fruit and fish.","explanation":"such as + examples.","explanation_ar":"such as + أمثلة.","stage":"guided","parts":["fruit and fish.","such as","Eat healthy food"],"target":["Eat healthy food","such as","fruit and fish."]},{"q":"Build a fact about sleep.","answer":"Children need → about ten hours → of sleep.","explanation":"A fact with a number.","explanation_ar":"حقيقة برقم.","stage":"guided","parts":["Children need","of sleep.","about ten hours"],"target":["Children need","about ten hours","of sleep."]},{"q":"Build a habit with instead of.","answer":"Walk → instead of → taking the car → for short trips.","explanation":"A habit with instead of.","explanation_ar":"عادة مع instead of.","stage":"guided","parts":["taking the car","for short trips.","instead of","Walk"],"target":["Walk","instead of","taking the car","for short trips."]},{"q":"Build a closing about heart habits.","answer":"That is why → a healthy heart → needs good habits.","explanation":"Closing sentence.","explanation_ar":"جملة ختامية.","stage":"guided","parts":["needs good habits.","That is why","a healthy heart"],"target":["That is why","a healthy heart","needs good habits."]}]},{"id":"RW-L03-U4-LS5-A3","type":"organizer","stage":"freer","instructions":"Organizer: Plan your Hamburger.","instructions_ar":"خطط للهامبرغر.","items":[{"q":"Write your topic sentence.","answer":"A healthy heart needs a few simple habits.","explanation":"Main idea.","explanation_ar":"الفكرة الرئيسية.","dok":1,"skill":"planning","stage":"freer"},{"q":"Habit 1 + a fact or an example.","answer":"be active – for example, I swim on Fridays","explanation":"Habit + support.","explanation_ar":"عادة + دعم.","dok":2,"skill":"planning","stage":"freer"},{"q":"Habit 2 + a fact or an example.","answer":"sleep about ten hours – sleep helps the body repair muscles","explanation":"Habit + support.","explanation_ar":"عادة + دعم.","dok":2,"skill":"planning","stage":"freer"},{"q":"Habit 3 + a fact or an example, and your closing.","answer":"less screen time – go outside and play instead; That is why…","explanation":"Habit + support + closing.","explanation_ar":"عادة + دعم + خاتمة.","dok":2,"skill":"planning","stage":"freer"}]},{"id":"RW-L03-U4-LS5-A4","type":"writing","stage":"production","instructions":"Writing: Write, revise, edit and publish your paragraph.","instructions_ar":"اكتب فقرتك وحسّنها ودققها وانشرها.","items":[{"q":"Write your topic sentence and habit 1 with an example.","answer":"There are three easy ways to keep your heart healthy. First, be active for one hour every day. For example, you can play football or swim.","explanation":"Topic + habit + example.","explanation_ar":"رئيسية + عادة + مثال.","dok":2,"skill":"writing","stage":"production"},{"q":"Write habits 2 and 3, each with a fact or an example.","answer":"Also, eat healthy food such as fruit and fish. In addition, drink water instead of soda, because soda has a lot of sugar.","explanation":"Two supported habits.","explanation_ar":"عادتان مدعومتان.","dok":2,"skill":"writing","stage":"production"},{"q":"Write your closing sentence about heart habits.","answer":"That is why these simple habits help your heart work hard for your whole life.","explanation":"Closing.","explanation_ar":"خاتمة.","dok":2,"skill":"writing","stage":"production"},{"q":"Write one opinion you changed into a fact.","answer":"Before: Soda is disgusting. After: Soda has a lot of sugar.","explanation":"Before → after.","explanation_ar":"قبل ← بعد.","dok":3,"skill":"revising","stage":"production","_w":{"checklist":[],"min":null,"max":null}}]},{"id":"RW-L03-U4-LS5-ORG","type":"organizer","organizer":"Hamburger Plan","instructions":"Organizer: Write your topic sentence on the top bun, one habit with its fact or example on each layer, and your closing on the bottom bun.","items":[{"q":"Top bun – topic sentence","answer":"There are three easy ways to keep your heart healthy."},{"q":"Layer 1 – habit + fact/example","answer":"be active one hour a day – for example, football, swimming, bicycle"},{"q":"Layer 2 – habit + fact/example","answer":"eat healthy food such as fruit, vegetables and fish – energy without too much sugar"},{"q":"Layer 3 – habit + fact/example","answer":"drink water instead of soda – soda has a lot of sugar, water has none"},{"q":"Bottom bun – closing","answer":"That is why these simple habits help your heart work hard for your whole life."}]},{"id":"RW-L03-U4-LS5-WR","type":"writing","instructions":"Writing: Write an informative paragraph: \"How to Keep My Heart Healthy\" (6–8 sentences). Give three healthy habits and support each one with a fact or an example. Write an informative paragraph: \"How to Keep My Heart Healthy\" (6–8 sentences). Give three healthy habits and support each one with a fact or an example.","instructions_ar":"اكتب فقرة معلوماتية بعنوان «كيف أحافظ على صحة قلبي» (6–8 جمل)، اذكر فيها ثلاث عادات صحية وادعم كلًّا منها بحقيقة أو مثال.","prompt":"Write an informative paragraph: \"How to Keep My Heart Healthy\" (6–8 sentences). Give three healthy habits and support each one with a fact or an example.","checklist":["My topic sentence tells the main idea.","I wrote three healthy habits.","Each habit has a fact or an example.","I used For example, (with a comma) or such as (no comma).","I used linking words (First, Also, In addition, That is why).","I used at least three unit words (heart, blood, exercise, muscles…).","My details are facts, not opinions; capitals, periods and -s endings are correct."],"rubric_id":"RW-RUBRIC-5T","min_words":75,"max_words":150,"organizer":"Hamburger Plan (topic sentence – 3 habits + support – closing)","items":[{"q":"Write an informative paragraph: \"How to Keep My Heart Healthy\" (6–8 sentences). Give three healthy habits and support each one with a fact or an example.","answer":"There are three easy ways to keep your heart healthy. First, be active for one hour every day. For example, you can play football, swim or ride a bicycle. Also, eat healthy food such as fruit, vegetables and fish. These foods give your body energy without too much sugar. In addition, drink water instead of soda, because soda has a lot of sugar and water has none. That is why these simple habits help your heart work hard for your whole life.","_w":{"checklist":["My topic sentence tells the main idea.","I wrote three healthy habits.","Each habit has a fact or an example.","I used For example, (with a comma) or such as (no comma).","I used linking words (First, Also, In addition, That is why).","I used at least three unit words (heart, blood, exercise, muscles…).","My details are facts, not opinions; capitals, periods and -s endings are correct."],"min":75,"max":150}}]}],"game":{"name":"Healthy Heart Race","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Heart runner: a heart runs along a track; at each stop the child matches a habit to its fact or example. Correct matches make the heart run faster; opinions slow it down.","Teams roll the die and move their heart.","On each space, they draw a habit card and find the matching support card.","They read the habit and support aloud.","If the support is an opinion, they must change it to a fact to move on.","The first heart to reach the finish line wins."],"data":[]},"exit_quiz":[{"q":"What is the purpose of *How to Keep My Heart Healthy*?","answer":"to inform readers how to keep their hearts healthy","explanation":"Informative paragraph.","explanation_ar":"إعلام القرّاء.","options":["to tell a funny story","to inform readers how to keep their hearts healthy","to invite a friend","to describe a trip"],"dok":1,"skill":"author's purpose"},{"q":"How many habits should your paragraph give?","answer":"three","explanation":"Three habits.","explanation_ar":"ثلاث.","options":["three","one","ten","none"],"dok":1,"skill":"paragraph structure"},{"q":"*Active children have strong hearts.* *Active* means ___.","answer":"moving a lot","explanation":"Active = moving.","explanation_ar":"نشيط.","options":["sleeping a lot","eating a lot","moving a lot","sitting all day"],"dok":1,"skill":"vocabulary"},{"q":"Which detail is a FACT?","answer":"Soda has a lot of sugar.","explanation":"Checkable.","explanation_ar":"حقيقة.","options":["Soda has a lot of sugar.","Soda is disgusting.","I hate soda.","Soda is the worst drink ever."],"dok":1,"skill":"fact vs. opinion"},{"q":"Which sentence about food uses *such as* correctly?","answer":"Eat vegetables such as carrots and cucumbers.","explanation":"No comma after such as.","explanation_ar":"صحيحة.","options":["Eat vegetables such as carrots and cucumbers.","Eat vegetables such as, carrots.","Eat vegetables, such as, carrots.","Such as eat vegetables carrots."],"dok":2,"skill":"punctuation"},{"q":"Which sentence about exercise is correct?","answer":"Exercise makes your heart strong.","explanation":"Exercise → makes.","explanation_ar":"makes.","options":["Exercise make your heart strong.","Exercise making your heart strong.","Exercise makes your heart strong.","Exercises makes your heart strong."],"dok":2,"skill":"grammar"},{"q":"Which closing sentence is best?","answer":"That is why simple habits help your heart for your whole life.","explanation":"Closing in new words.","explanation_ar":"خاتمة مناسبة.","options":["There are three ways to keep your heart healthy.","First, be active.","Do you like soda?","That is why simple habits help your heart for your whole life."],"dok":2,"skill":"closing"},{"q":"A partner wrote *Eat vegetables.* with no support. What should they add?","answer":"a fact or an example, like 'such as carrots, which help your body'","explanation":"Add support.","explanation_ar":"حقيقة أو مثال.","options":["a second topic sentence","a question","a fact or an example, like 'such as carrots, which help your body'","a funny joke"],"dok":2,"skill":"revising"},{"q":"Why should you keep the paragraph general and not write about a classmate's health?","answer":"Health is private, and the paragraph is advice for everyone.","explanation":"Respect privacy.","explanation_ar":"الصحة أمر خاص.","options":["Classmates are boring.","Names are hard to spell.","It makes the paragraph shorter.","Health is private, and the paragraph is advice for everyone."],"dok":3,"skill":"audience and respect"},{"q":"Which paragraph is the MOST complete?","answer":"topic sentence, three habits each with a fact or example, linking words and a closing","explanation":"All parts present.","explanation_ar":"الأكثر اكتمالًا.","options":["one habit and a picture","topic sentence, three habits each with a fact or example, linking words and a closing","three opinions about soda","a list of foods with no sentences"],"dok":3,"skill":"evaluate"}],"images":[{"id":"IMG-RW-L03-U4-LS5-V01","prompt":"Picture for the word 'healthy': a bowl of fruit with a green check"},{"id":"IMG-RW-L03-U4-LS5-V02","prompt":"Picture for the word 'habit': a calendar with a walking icon every day"},{"id":"IMG-RW-L03-U4-LS5-V03","prompt":"Picture for the word 'vegetables': carrots, cucumbers and tomatoes"},{"id":"IMG-RW-L03-U4-LS5-V04","prompt":"Picture for the word 'sugar': sugar cubes next to a soda can"},{"id":"IMG-RW-L03-U4-LS5-V05","prompt":"Picture for the word 'leaflet': a folded colorful leaflet"},{"id":"IMG-RW-L03-U4-LS5-V06","prompt":"Picture for the word 'instead of': a water bottle replacing a soda can"},{"id":"IMG-RW-L03-U4-LS5-V07","prompt":"Picture for the word 'active': children running and climbing"},{"id":"IMG-RW-L03-U4-LS5-01","prompt":"Omar hands out a heart-health leaflet."},{"id":"IMG-RW-L03-U4-LS5-02","prompt":"A heart-themed hamburger organizer."},{"id":"IMG-RW-L03-U4-LS5-03","prompt":"Water compared with sugary soda."}],"audio":[{"id":"AUD-RW-L03-U4-LS5-V01","script":"healthy. Fruit is a healthy snack."},{"id":"AUD-RW-L03-U4-LS5-V02","script":"habit. Walking every day is a good habit."},{"id":"AUD-RW-L03-U4-LS5-V03","script":"vegetables. Eat vegetables at every meal."},{"id":"AUD-RW-L03-U4-LS5-V04","script":"sugar. Soda has a lot of sugar."},{"id":"AUD-RW-L03-U4-LS5-V05","script":"leaflet. We made a leaflet about healthy hearts."},{"id":"AUD-RW-L03-U4-LS5-V06","script":"instead of. Drink water instead of soda."},{"id":"AUD-RW-L03-U4-LS5-V07","script":"active. Active children have strong hearts."},{"id":"AUD-RW-L03-U4-LS5-VID","script":"Coach Omar has three tips for a healthy heart! Plan with a hamburger: topic sentence, three habits with support, a closing! There are three easy ways to keep your heart healthy. First, be active for one hour every day. For example… Revise: every habit needs a fact or an example! 'Soda is disgusting' – opinion! Change it to a fact. Edit: For example, (comma) · such as (no comma) · makes/make. Publish: Omar's 'Healthy Heart' leaflet goes to every class!"}]}],"unit_test":[{"q":"Your ___ hold your body up and protect parts inside you.","answer":"bones","explanation":"Bones = support.","explanation_ar":"العظام.","options":["bones","lungs","teeth","blood"],"dok":1,"skill":"body parts","_part":"Part A – Vocabulary"},{"q":"We ___ in and out all day without thinking.","answer":"breathe","explanation":"Breathe = take in air.","explanation_ar":"نتنفس.","options":["repair","pump","memorize","breathe"],"dok":1,"skill":"vocabulary","_part":"Part A – Vocabulary"},{"q":"Your ___ covers and protects your whole body.","answer":"skin","explanation":"Skin = outside cover.","explanation_ar":"الجلد.","options":["stomach","skin","brain","heart"],"dok":1,"skill":"body parts","_part":"Part A – Vocabulary"},{"q":"After football, sit in the shade and ___.","answer":"rest","explanation":"Rest = relax.","explanation_ar":"استرح.","options":["breathe out forever","unlock","persuade","rest"],"dok":1,"skill":"vocabulary","_part":"Part A – Vocabulary"},{"q":"*Eating only candy is unhealthy.* *Unhealthy* means ___.","answer":"not healthy","explanation":"un- = not.","explanation_ar":"غير صحي.","options":["healthy again","not healthy","very healthy","full of health"],"dok":1,"skill":"prefixes","_part":"Part A – Vocabulary"},{"q":"*Please reread the question before you answer.* *Reread* means ___.","answer":"read again","explanation":"re- = again.","explanation_ar":"أعد القراءة.","options":["read again","not read","read quickly","read aloud"],"dok":1,"skill":"prefixes","_part":"Part A – Vocabulary"},{"q":"Which word has a prefix that means *again*?","answer":"rewrite","explanation":"re + write.","explanation_ar":"rewrite.","options":["red","ready","rewrite","under"],"dok":2,"skill":"prefixes","_part":"Part A – Vocabulary"},{"q":"*The function of your teeth is to bite and chew food.* *Function* means ___.","answer":"job","explanation":"Function = job.","explanation_ar":"وظيفة.","options":["color","size","job","name"],"dok":2,"skill":"vocabulary in context","_part":"Part A – Vocabulary"},{"q":"Which sentence about teeth is a FACT?","answer":"Adults have 32 teeth.","explanation":"Checkable.","explanation_ar":"حقيقة.","options":["Teeth are the best part of the face.","Brushing is boring.","White teeth are prettier.","Adults have 32 teeth."],"dok":1,"skill":"fact vs. opinion","_part":"Part D – Writing skills"},{"q":"Which sentence about playing outside uses *For example* correctly?","answer":"For example, I play outside every afternoon.","explanation":"Comma after For example.","explanation_ar":"صحيحة.","options":["For example, I play outside every afternoon.","For example I play outside every afternoon.","For, example I play outside.","I play for example, outside."],"dok":1,"skill":"punctuation","_part":"Part D – Writing skills"},{"q":"Which example BEST supports *Sleep helps your brain*?","answer":"For example, I remember my lessons better after a good night's sleep.","explanation":"It shows the detail.","explanation_ar":"يدعم التفصيل.","options":["For example, I like my blue pillow.","For example, I remember my lessons better after a good night's sleep.","For example, cats sleep a lot.","For example, beds are soft."],"dok":2,"skill":"relevant examples","_part":"Part D – Writing skills"},{"q":"A poster says *Wash your hands before every meal!* What is its purpose?","answer":"to persuade","explanation":"It tells you what to do.","explanation_ar":"الإقناع.","options":["to entertain","to persuade","to tell a story","to describe a trip"],"dok":1,"skill":"author's purpose","_part":"Part D – Writing skills"},{"q":"Which sentence about fruit uses *such as* correctly?","answer":"Eat fruit such as oranges and grapes.","explanation":"No comma after such as.","explanation_ar":"صحيحة.","options":["Eat fruit such as oranges and grapes.","Eat fruit such as, oranges.","Eat fruit, such as, grapes.","Such as eat fruit grapes."],"dok":2,"skill":"such as","_part":"Part D – Writing skills"},{"q":"Which detail about walking is BEST supported?","answer":"Walking is good for you. It makes your heart stronger. For example, my grandmother walks every day and feels great.","explanation":"Detail + fact + example.","explanation_ar":"مدعوم جيدًا.","options":["Walking is good.","Walking. I like it.","Walking is good for you. It makes your heart stronger. For example, my grandmother walks every day and feels great.","Walking is good because walking."],"dok":3,"skill":"evaluate","_part":"Part D – Writing skills"}],"unit_writing":{"task":"Write an informative paragraph: \"How to Keep My Lungs (or Teeth) Healthy\". Give a topic sentence, three habits, a fact or an example for each habit, and a closing sentence.","model":"There are three important ways to keep your teeth healthy. First, brush your teeth twice a day for two minutes. For example, I brush after breakfast and before bed. Also, eat less candy and drink less soda, because sugar can make holes in your teeth. In addition, eat crunchy foods such as carrots and apples, which help clean your teeth. Finally, visit the dentist every six months. That is why these simple habits can give you a healthy smile for life.","marks":20}});
